41: struct ExecutionEpisodeSnapshot final {
42:   std::uint64_t localization_epoch{0U};
43:   // Desired identity can advance during a hot retarget while the active
44:   // command still belongs to the previous waypoint. Keep that execution
45:   // identity until the successor bundle is actually committed.
46:   std::uint64_t goal_epoch{0U};
47:   std::uint64_t request_id{0U};
48:   std::uint64_t active_command_goal_epoch{0U};
49:   std::uint64_t active_command_request_id{0U};
50:   std::uint64_t active_generation{0U};
51:   ExecutionEpisodePhase phase{ExecutionEpisodePhase::kInitialHold};
52:   bool command_available{false};
53:   bool failure_latched{false};
54:   bool safety_suffix_active{false};
55:   bool restart_from_rest{false};
56:   // Recovery policy is part of this same physical-execution snapshot. It is
57:   // intentionally distinct from sampled phase (for example, a terminal MAIN
58:   // can already be emitting STOPPED_HOLD while completion is still pending),
59:   // but it no longer has an independently mutable owner.
60:   ExecutionRecoveryState recovery_state{ExecutionRecoveryState::kInitialHold};
61: };
