63: // One lifecycle record for an execution episode. Policy code reads this
64: // snapshot instead of reconstructing physical state from worker flags.
65: class ExecutionEpisode final {
66:  public:
67:   [[nodiscard]] ExecutionEpisodeSnapshot snapshot() const noexcept {
68:     std::lock_guard lock(mutex_);
69:     return state_;
70:   }
71: 
72:   void reset(std::uint64_t localization_epoch) noexcept {
73:     std::lock_guard lock(mutex_);
74:     state_ = {};
75:     state_.localization_epoch = localization_epoch;
76:     state_.phase = ExecutionEpisodePhase::kInitialHold;
77:     state_.recovery_state = ExecutionRecoveryState::kInitialHold;
78:   }

80:   void beginGoal(std::uint64_t localization_epoch, std::uint64_t goal_epoch,
81:                  std::uint64_t request_id, bool retain_command) noexcept {
82:     std::lock_guard lock(mutex_);
83:     const bool retaining_active_command = retain_command && state_.command_available &&
84:         state_.active_generation != 0U &&
85:         state_.localization_epoch == localization_epoch;
86:     state_.localization_epoch = localization_epoch;
87:     state_.goal_epoch = goal_epoch;
88:     state_.request_id = request_id;
89:     if (retaining_active_command) {
90:       // A hot-retarget changes desired ownership, not the identity/role of the
91:       // command still being sampled. Its observations remain valid until the
92:       // replacement command wins timeline activation.
93:       return;
94:     }
95:     state_.active_command_goal_epoch = 0U;
96:     state_.active_command_request_id = 0U;
97:     state_.phase = ExecutionEpisodePhase::kInitialHold;
98:     state_.command_available = false;
99:     state_.failure_latched = false;
100:     state_.safety_suffix_active = false;
101:     state_.restart_from_rest = false;
102:     state_.recovery_state = ExecutionRecoveryState::kInitialHold;
103:     state_.active_generation = 0U;
104:   }
105: 
106:   void commandCommitted(
107:       const navigation_planning::CandidateBundle& bundle) noexcept {
108:     std::lock_guard lock(mutex_);
109:     if (state_.failure_latched || !bundleIdentityMatchesEpisode(bundle) ||
110:         bundle.bundle_generation <= state_.active_generation) {
111:       return;
112:     }
113:     state_.active_command_goal_epoch = bundle.goal_epoch;
114:     state_.active_command_request_id = bundle.request_id;
115:     state_.active_generation = bundle.bundle_generation;
116:     state_.command_available = true;
117:     state_.failure_latched = false;
118:     state_.safety_suffix_active =
119:         bundle.role == navigation_planning::CandidateRole::kBackup ||
120:         bundle.role == navigation_planning::CandidateRole::kEmergency;
121:     state_.phase = bundle.role == navigation_planning::CandidateRole::kEmergency ||
122:         bundle.role == navigation_planning::CandidateRole::kBackup
123:         ? ExecutionEpisodePhase::kTrackingBackup
124:         : ExecutionEpisodePhase::kTrackingMain;
125:     const auto recovery_event = bundle.role == navigation_planning::CandidateRole::kEmergency
126:         ? ExecutionRecoveryEvent::kEmergencyCommitted
127:         : bundle.role == navigation_planning::CandidateRole::kBackup
128:         ? ExecutionRecoveryEvent::kBackupActivated
129:         : ExecutionRecoveryEvent::kMainCommitted;
130:     state_.recovery_state = transitionExecutionRecovery(
131:         state_.recovery_state, recovery_event);
132:   }

134:   bool observeRetainedCommand(
135:       const navigation_planning::CandidateBundle& bundle,
136:       bool safety_suffix_active) noexcept {
137:     std::lock_guard lock(mutex_);
138:     if (state_.failure_latched || !activeBundleIdentityMatches(bundle)) {
139:       return false;
140:     }
141:     state_.command_available = true;
142:     state_.safety_suffix_active = safety_suffix_active;
143:     if (bundle.role == navigation_planning::CandidateRole::kEmergency ||
144:         bundle.role == navigation_planning::CandidateRole::kBackup) {
145:       state_.phase = ExecutionEpisodePhase::kTrackingBackup;
146:     } else {
147:       state_.phase = ExecutionEpisodePhase::kTrackingMain;
148:     }
149:     return true;
150:   }
151: 
152:   bool observeSampledSafetyRole(
153:       const navigation_planning::CandidateBundle& bundle,
154:       navigation_planning::CandidateRole sampled_role) noexcept {
155:     std::lock_guard lock(mutex_);
156:     if (state_.failure_latched || !activeBundleIdentityMatches(bundle) ||
157:         (sampled_role != navigation_planning::CandidateRole::kBackup &&
158:          sampled_role != navigation_planning::CandidateRole::kEmergency)) {
159:       return false;
160:     }
161:     state_.phase = ExecutionEpisodePhase::kTrackingBackup;
162:     state_.safety_suffix_active = true;
163:     const auto event = sampled_role == navigation_planning::CandidateRole::kEmergency
164:         ? ExecutionRecoveryEvent::kEmergencyCommitted
165:         : ExecutionRecoveryEvent::kBackupActivated;
166:     state_.recovery_state = transitionExecutionRecovery(
167:         state_.recovery_state, event);
168:     return true;
169:   }
170: 
171:   bool preserveSafetySuffix(
172:       const navigation_planning::CandidateBundle& bundle) noexcept {
173:     std::lock_guard lock(mutex_);
174:     if (state_.failure_latched || !state_.command_available ||
175:         !activeBundleIdentityMatches(bundle)) {
176:       return false;
177:     }
178:     state_.safety_suffix_active = true;
179:     return true;
180:   }
181: 
182:   bool requestRestartFromRest(
183:       const navigation_planning::CandidateBundle& bundle) noexcept {
184:     std::lock_guard lock(mutex_);
185:     if (state_.failure_latched || !activeBundleIdentityMatches(bundle)) return false;
186:     state_.restart_from_rest = true;
187:     return true;
188:   }
189: 
190:   void clearRestartFromRest() noexcept {
191:     std::lock_guard lock(mutex_);
192:     state_.restart_from_rest = false;
193:   }
194: 
195:   bool applyRecoveryEvent(
196:       ExecutionRecoveryEvent event,
197:       const navigation_planning::CandidateBundle& bundle) noexcept {
198:     std::lock_guard lock(mutex_);
199:     if (state_.failure_latched || !activeBundleIdentityMatches(bundle)) return false;
200:     state_.recovery_state = transitionExecutionRecovery(
201:         state_.recovery_state, event);
202:     return true;
203:   }
204: 
205:   bool stoppedHold(
206:       const navigation_planning::CandidateBundle& bundle) noexcept {
207:     std::lock_guard lock(mutex_);
208:     if (state_.failure_latched || !activeBundleIdentityMatches(bundle)) return false;
209:     // A stopped hold is also the command publisher's representation while a
210:     // measured-state PlanFromRest retry is in flight.  Do not erase that
211:     // lifecycle request from the 50 Hz hold samples; otherwise the next
212:     // non-zero odometry sample is misclassified as motion without an
213:     // authorized recovery and the node falls through to PX4 Hold.
214:     const bool restart_requested = state_.restart_from_rest;
215:     state_.active_generation = bundle.bundle_generation;
216:     state_.phase = ExecutionEpisodePhase::kStoppedHold;
217:     state_.command_available = true;
218:     state_.safety_suffix_active = false;
219:     state_.restart_from_rest = restart_requested;
220:     return true;

221:   }
222: 
223:   void failClosed() noexcept {
224:     std::lock_guard lock(mutex_);
225:     state_.phase = ExecutionEpisodePhase::kPx4Hold;
226:     state_.command_available = false;
227:     state_.failure_latched = true;
228:     state_.safety_suffix_active = false;
229:     state_.restart_from_rest = false;
230:     state_.recovery_state = ExecutionRecoveryState::kPx4Hold;
231:   }
232: 
233:   void suspendCommand() noexcept {
234:     std::lock_guard lock(mutex_);
235:     state_.command_available = false;
236:   }
237: 
238:   void clearGoal(std::uint64_t localization_epoch) noexcept {
239:     std::lock_guard lock(mutex_);
240:     state_ = {};
241:     state_.localization_epoch = localization_epoch;
242:     state_.phase = ExecutionEpisodePhase::kInitialHold;
243:     state_.recovery_state = ExecutionRecoveryState::kInitialHold;
244:   }
245: 
246:  private:
247:   [[nodiscard]] bool bundleIdentityMatchesEpisode(
248:       const navigation_planning::CandidateBundle& bundle) const noexcept {
249:     return bundle.localization_epoch != 0U && bundle.goal_epoch != 0U &&
250:            bundle.request_id != 0U && bundle.bundle_generation != 0U &&
251:            state_.localization_epoch == bundle.localization_epoch &&
252:            state_.goal_epoch == bundle.goal_epoch &&
253:            state_.request_id == bundle.request_id;
254:   }
255: 
256:   [[nodiscard]] bool activeBundleIdentityMatches(
257:       const navigation_planning::CandidateBundle& bundle) const noexcept {
258:     return bundle.localization_epoch != 0U && bundle.goal_epoch != 0U &&
259:            bundle.request_id != 0U && bundle.bundle_generation != 0U &&
260:            state_.localization_epoch == bundle.localization_epoch &&
261:            state_.active_command_goal_epoch == bundle.goal_epoch &&
262:            state_.active_command_request_id == bundle.request_id &&
263:            state_.active_generation == bundle.bundle_generation;
264:   }
265: 
266:   mutable std::mutex mutex_;
267:   ExecutionEpisodeSnapshot state_{};
268: };
