19: // Small sole-owner model for the runtime's single pending request. It makes
20: // callback/handoff interleavings explicit: enqueue, snapshot and consume are
21: // each linearizable operations under the caller's input/transition critical
22: // section, and consumption removes the exact request exactly once.
23: class PendingGoalHandoffOwner {
24:  public:
25:   using GoalConstPtr = navigation_contracts::msg::NavigationGoal::ConstSharedPtr;
26: 
27:   // The owner stores one immutable message, not a parallel identity and
28:   // message optional.  The caller must hold the runtime input/transition
29:   // transaction while deciding suffix ownership and invoking this method.
30:   bool enqueueGoal(const GoalConstPtr& candidate,
31:                   const std::optional<navigation_contracts::msg::NavigationGoal>& active,
32:                   bool safety_suffix_active) {
33:     if (!safety_suffix_active || !candidate || !active.has_value() ||
34:         candidate->mission_id != active->mission_id ||
35:         !goalMessageNewer(*candidate, *active)) return false;
36:     std::lock_guard<std::mutex> lock(goal_mutex_);
37:     if (pending_goal_ && !goalMessageNewer(*candidate, *pending_goal_)) {
38:       return false;
39:     }
40:     pending_goal_ = candidate;
41:     return true;
42:   }
43: 
44:   [[nodiscard]] GoalConstPtr goalSnapshot() const {
45:     std::lock_guard<std::mutex> lock(goal_mutex_);
46:     return pending_goal_;
47:   }
48: 
49:   // Peek and consume are separate so a stopped-suffix handoff can prepare a
50:   // new candidate before the pending request is removed from its sole owner.
51:   // The caller must consume the exact pointer only after the replacement
52:   // command has committed successfully.
53:   [[nodiscard]] bool consumeGoal(const GoalConstPtr& expected) {
54:     if (!expected) return false;
55:     std::lock_guard<std::mutex> lock(goal_mutex_);
56:     if (!pending_goal_ || pending_goal_.get() != expected.get()) return false;
57:     pending_goal_.reset();
58:     return true;
59:   }
60: 
61:   [[nodiscard]] bool goalMatchesStatus(
62:       const std::string& mission_id, std::uint32_t waypoint_index,
63:       std::uint64_t request_id) const {
64:     std::lock_guard<std::mutex> lock(goal_mutex_);
65:     return pending_goal_ && pending_goal_->mission_id == mission_id &&
66:            pending_goal_->waypoint_index == waypoint_index &&
67:            pending_goal_->request_id == request_id;
68:   }
69: 
70:   void clearGoal() {
71:     std::lock_guard<std::mutex> lock(goal_mutex_);
72:     pending_goal_.reset();
73:   }
74: 
75:  private:
76:   static bool goalMessageNewer(
77:       const navigation_contracts::msg::NavigationGoal& candidate,
78:       const navigation_contracts::msg::NavigationGoal& current) noexcept {
79:     if (candidate.mission_id != current.mission_id) return false;
80:     if (candidate.request_id != current.request_id) {
81:       return candidate.request_id > current.request_id;
82:     }
83:     if (candidate.waypoint_index != current.waypoint_index) {
84:       return candidate.waypoint_index > current.waypoint_index;
85:     }
86:     return candidate.route.route_revision > current.route.route_revision;
87:   }
88: 
89:   mutable std::mutex goal_mutex_;
90:   GoalConstPtr pending_goal_;
91: };

93: inline bool canHotRetargetAtWaypointTransition(
94:     bool same_logical_goal, bool previous_goal_was_pass_through,
95:     bool command_available, bool planner_failure_latched, bool safety_suffix_active) {
96:   // A committed safety suffix is a world-certified braking command, not a
97:   // goal-geometry claim. It cannot be rebound to a new goal: doing so would
98:   // let a new nominal solve relabel a moving BACKUP/EMERGENCY command as
99:   // TrackMain before certified stop/handover. Defer the retarget until the
100:   // suffix reaches a certified stop (or fail closed if it cannot).
101:   return !same_logical_goal && previous_goal_was_pass_through && command_available &&
102:          !planner_failure_latched && !safety_suffix_active;
103: }
104: 
105: // A terminal acknowledgement is not by itself permission to revoke the
106: // executing command.  A PASS_THROUGH predecessor may bridge the callback
107: // ordering boundary only when the next route leg and the immutable execution
108: // certificate are both still present.  The caller supplies facts captured
109: // under its lifecycle transaction; this predicate owns no mutable state.
110: struct PassThroughTerminalAckFacts final {
111:   bool successful_terminal_status{false};
112:   bool status_matches_active_identity{false};
113:   bool active_goal_is_pass_through{false};
114:   bool outgoing_route_exists{false};
115:   bool certified_main_command{false};
116:   bool certified_continuation_boundary{false};
117:   bool execution_identity_current{false};
118:   bool failure_latched{false};
119:   bool safety_suffix_active{false};
120:   bool command_exposure_allowed{false};
121:   bool command_lease_valid{false};
122: };
123: 
124: [[nodiscard]] inline bool passThroughTerminalAckMayRetainCommand(
125:     const PassThroughTerminalAckFacts& facts) noexcept {
126:   return facts.successful_terminal_status &&
127:          facts.status_matches_active_identity &&
128:          facts.active_goal_is_pass_through && facts.outgoing_route_exists &&
129:          facts.certified_main_command && facts.certified_continuation_boundary &&
130:          facts.execution_identity_current && !facts.failure_latched &&
131:          !facts.safety_suffix_active && facts.command_exposure_allowed &&
132:          facts.command_lease_valid;
133: }
