135: inline bool watchdogTimeoutMayRetainSafetySuffix(
136:     ExecutionRecoveryState state, bool command_available,
137:     bool safety_suffix_active) noexcept {
138:   const bool safety_state = state == ExecutionRecoveryState::kTrackBackup ||
139:                             state == ExecutionRecoveryState::kEmergencyBrake;
140:   return safety_state && command_available && safety_suffix_active;
141: }
