2038: void NavigationRuntimeNode::onGoal(
2039:     const navigation_contracts::msg::NavigationGoal::ConstSharedPtr& message) {
2040:   if (!message) {
2041:     RCLCPP_ERROR(get_logger(), "rejected null navigation goal");
2042:     return;
2043:   }
2044:   const auto route = decodeRouteSnapshot(*message);
2045:   const bool route_mirrors_valid =
2046:       route.has_value() && routeSnapshotMatchesGoalMirrors(*route, *message);
2047:   if (!route.has_value() || !route_mirrors_valid) {
2048:     // This message was never accepted as a lifecycle event.  It must not
2049:     // revoke a certified active command or a newer pending goal.
2050:     RCLCPP_ERROR(get_logger(), "rejected navigation goal: immutable route snapshot is invalid");
2051:     return;
2052:   }
2053:   {
2054:     std::unique_lock<std::mutex> localization_lock(localization_transition_mutex_);
2055:     std::lock_guard<std::mutex> lock(input_mutex_);
2056:     applyValidatedGoalLocked(message);
2057:   }
2058:         if (consumeForeignMissionCancelIfCurrent() && planning_worker_) {
2059:           planning_worker_->cancelActive();
2060:         }
2061: }
