2063: void NavigationRuntimeNode::transitionForeignMissionLocked(
2064:     const bool defer_until_certified_stop) {
2065:   // This helper is called only with input_mutex_ -> transitionMutex() held.
2066:   // A foreign mission is not ordered by request_id: it is a control-authority
2067:   // violation.  While moving, preserve the certified suffix and defer the
2068:   // same complete transition until measured stop; otherwise fail closed now.
2069:   if (defer_until_certified_stop) {
2070:     foreign_mission_hold_after_stop_ = true;
2071:     pending_goal_owner_.clearGoal();
2072:     deferred_terminal_status_.reset();
2073:     return;
2074:   }
2075:   // The worker interrupt is deliberately post-action: cancelActive() may
2076:   // enter backend code and must not run while lifecycle locks are held.
2077:   foreign_cancel_target_epoch_ = active_goal_epoch_.load(std::memory_order_acquire);
2078:   foreign_cancel_localization_epoch_ =
2079:       active_localization_epoch_.load(std::memory_order_acquire);
2080:   foreign_mission_cancel_pending_.store(true, std::memory_order_release);
2081:   pending_goal_owner_.clearGoal();
2082:   deferred_terminal_status_.reset();
2083:   foreign_mission_hold_after_stop_ = false;
2084:   const auto next_goal_epoch = advanceMonotonicId(active_goal_epoch_);
2085:   if (next_goal_epoch) {
2086:     foreign_cancel_transition_epoch_ = *next_goal_epoch;
2087:     (void)command_bundle_store_.setActiveGoalEpoch(*next_goal_epoch, false);
2088:   } else {
2089:     command_bundle_store_.invalidate();
2090:   }
2091:   active_goal_.reset();
2092:   executing_goal_.reset();
2093:   command_bundle_store_.invalidate();
2094:   new_goal_ = false;
2095:   hot_goal_transition_ = false;
2096:   execution_episode_.clearRestartFromRest();
2097:   failClosedLocked();
2098:   mission_start_position_world_.reset();
2099:   mission_start_mission_id_.clear();
2100:   mission_start_route_revision_ = 0U;
2101:   mission_start_localization_epoch_ = 0U;
2102:   plan_from_rest_first_failure_steady_ns_ = 0;
2103:   skip_replan_once_.store(false, std::memory_order_release);
2104:   trajectory_reaches_goal_.store(false, std::memory_order_release);
2105:   terminal_bundle_generation_.store(0U, std::memory_order_release);
2106:   command_goal_epoch_.store(0U, std::memory_order_release);
2107: }
