2109: bool NavigationRuntimeNode::consumeForeignMissionCancelIfCurrentLocked() {
2110:   if (!foreign_mission_cancel_pending_.load(std::memory_order_acquire)) return false;
2111:   const bool unchanged = !active_goal_.has_value() &&
2112:       active_goal_epoch_.load(std::memory_order_acquire) ==
2113:           foreign_cancel_transition_epoch_ &&
2114:       active_localization_epoch_.load(std::memory_order_acquire) ==
2115:           foreign_cancel_localization_epoch_;
2116:   foreign_mission_cancel_pending_.store(false, std::memory_order_release);
2117:   return unchanged;
2118: }
