2120: bool NavigationRuntimeNode::consumeForeignMissionCancelIfCurrent() {
2121:   std::lock_guard<std::mutex> localization_lock(localization_transition_mutex_);
2122:   std::lock_guard<std::mutex> input_lock(input_mutex_);
2123:   return consumeForeignMissionCancelIfCurrentLocked();
2124: }
