2126: void NavigationRuntimeNode::applyValidatedGoalLocked(
2127:     const navigation_contracts::msg::NavigationGoal::ConstSharedPtr& message,
2128:     const bool execution_transition_held) {
2129:   // All command-lifecycle decisions are serialized after input_mutex_.  This
2130:   // prevents a publisher from clearing suffix ownership between the suffix
2131:   // read and pending-goal mutation.
2132:   std::unique_lock<std::mutex> command_lock(
2133:       command_execution_lease_failure_latch_.transitionMutex(), std::defer_lock);
2134:   if (!execution_transition_held) command_lock.lock();
2135:   if (foreign_mission_hold_after_stop_) {
2136:     // A foreign mission latch is terminal for the current control authority.
2137:     // No inbound goal may replace the cleared/held identity until an explicit
2138:     // authority reset resolves the latch after measured-stop evidence.
2139:     RCLCPP_ERROR(get_logger(),
2140:                  "rejected navigation goal while foreign mission Hold latch is active");
2141:     return;
2142:   }
2143:   // A planner backend plan is owned by the mission waypoint identity.  The
2144:   // continuation point is only look-ahead metadata; treating it as the
2145:   // current goal makes a repeated waypoint publication look like a new
2146:   // request (or, conversely, hides the actual waypoint transition).
2147:   const bool same_checkpoint = active_goal_.has_value() &&
2148:       active_goal_->mission_id == message->mission_id &&
2149:       active_goal_->waypoint_index == message->waypoint_index;
2150:   const bool same_logical_goal = same_checkpoint &&
2151:       active_goal_->request_id == message->request_id;
2152:   if (active_goal_.has_value() && !same_logical_goal) {
2153:     if (message->mission_id == active_goal_->mission_id &&
2154:         !goalIdentityNewer(*message, *active_goal_)) {
2155:       RCLCPP_WARN(get_logger(), "rejected stale/non-newer navigation goal request=%lu",
2156:                   static_cast<unsigned long>(message->request_id));
2157:       return;
2158:     }
2159:   }
2160:   const auto episode = execution_episode_.snapshot();
2161:   const bool previous_safety_suffix_active = episode.safety_suffix_active;
2162:   const bool can_hot_retarget = canHotRetargetAtWaypointTransition(
2163:       same_logical_goal,
2164:       active_goal_.has_value() &&
2165:           active_goal_->behavior ==
2166:               navigation_contracts::msg::NavigationGoal::BEHAVIOR_PASS_THROUGH,
2167:       episode.command_available, episode.failure_latched,
2168:       episode.safety_suffix_active);
2169:   bool effective_hot_retarget = can_hot_retarget;
2170:   if (!same_logical_goal) {
2171:     if (previous_safety_suffix_active) {
2172:       // A moving BACKUP/EMERGENCY suffix owns the command until certified
2173:       // stop. External Mode publishes a goal once, so returning here would
2174:       // lose the request permanently. Keep one validated, monotonic pending
2175:       // request without rebinding or revoking the suffix.
2176:       if (message->mission_id != active_goal_->mission_id) {
2177:         // A new mission has no ordering relation to the moving suffix. Keep
2178:         // the certified suffix, but remember one control-authority violation
2179:         // for the measured-stop transaction; do not queue or require retry.
2180:         transitionForeignMissionLocked(true);
2181:         RCLCPP_ERROR(get_logger(),
2182:                      "foreign mission observed while safety suffix drains; "
2183:                      "holding after certified stop active=%s incoming=%s",
2184:                      active_goal_->mission_id.c_str(), message->mission_id.c_str());
2185:         return;
2186:       }
2187:       const bool accepted_pending = pending_goal_owner_.enqueueGoal(
2188:           message, active_goal_,
2189:           episode.safety_suffix_active);
2190:       RCLCPP_WARN_THROTTLE(
2191:           get_logger(), *get_clock(), 1000,
2192:           "retaining pending navigation goal request=%lu while safety suffix drains accepted=%d",
2193:           static_cast<unsigned long>(message->request_id), accepted_pending ? 1 : 0);
2194:       return;
2195:     }
