2419: navigation_execution::CommitDecision NavigationRuntimeNode::admitImmediateCandidate(
2420:     const navigation_contracts::msg::NavigationGoal& goal,
2421:     const navigation_execution::CommitToken& token,
2422:     const std::shared_ptr<const navigation_planning::CandidateBundle>& candidate,
2423:     const navigation_execution::ExecutionTimelineSnapshot& predecessor,
2424:     const PlanningKey& key,
2425:     const std::shared_ptr<const navigation_execution::ExecutionStateLease>& measured_state,
2426:     const std::int64_t maximum_world_age_ns,
2427:     const std::optional<TerminalMonitorBoundary>& terminal_monitor) {
2428:   if (!candidate || !key.valid() ||
2429:       (terminal_monitor &&
2430:        candidate->kind != navigation_planning::CandidateBundleKind::kEmergencyBrake)) {
2431:     return navigation_execution::CommitDecision::kInvalidCandidate;
2432:   }
2433:   // Allocate the desired-goal copy before taking owners; retire the old goal
2434:   // after their guards release. Backend ACK and world validation stay outside.
2435:   std::optional<navigation_contracts::msg::NavigationGoal> prepared_goal{goal};
2436:   // Prepared validation stays outside this owner transaction. The admission
2437:   // predicate reads only clocks/captured metadata and never re-enters owners.
2438:   std::lock_guard<std::mutex> localization_lock(localization_transition_mutex_);
2439:   std::lock_guard<std::mutex> input_lock(input_mutex_);
2440:   std::lock_guard<std::mutex> command_lock(
2441:       command_execution_lease_failure_latch_.transitionMutex());
2442:   const auto current_episode = execution_episode_.snapshot();
2443:   const auto current_world = world_snapshot_store_.load();
2444:   const bool owner_current = !current_episode.failure_latched &&
2445:       desiredGoalIdentityMatchesLocked(goal, token.goal_epoch, candidate->localization_epoch) &&
2446:       active_goal_->route.route_revision == key.route_revision &&
2447:       key.localization_epoch == candidate->localization_epoch &&
2448:       key.goal_epoch == token.goal_epoch && key.request_id == candidate->request_id &&
2449:       key.dynamics_hash == dynamics_hash_ &&
2450:       key.committed_bundle_generation ==
2451:           (predecessor.active ? predecessor.active->bundle_generation : 0U) &&
2452:       current_world && current_world.identity.generation == key.pinned_world_generation &&
2453:       navigation_world_model::sameWorldSnapshotIdentity(
2454:           current_world.identity, candidate->world_identity) &&
2455:       command_execution_lease_failure_latch_.allowsCommandExposure();
2456:   const bool terminal_owner_current = !terminal_monitor ||
2457:       (predecessor.active && !new_goal_ && !hot_goal_transition_ &&
2458:        executingCommandIdentityMatchesLocked(
2459:           goal, token.goal_epoch, candidate->localization_epoch,
2460:           predecessor.active->bundle_generation) &&
2461:        executionEpisodeSnapshotsEqual(current_episode, terminal_monitor->episode) &&
2462:        !terminalHoldIsPending(
2463:           current_episode.command_available, trajectory_reaches_goal_.load(std::memory_order_acquire),
2464:           true, terminal_bundle_generation_.load(std::memory_order_acquire)));
2465:   const auto decision = owner_current && terminal_owner_current
2466:       ? command_bundle_store_.tryCommitIfCurrent(token, predecessor, candidate, [&] {
2467:           const auto admission_now_ns = now().nanoseconds();
2468:           return (!terminal_monitor || terminalMainMonitorPhaseIsOpen(
2469:                       *predecessor.active, current_episode, admission_now_ns)) &&
2470:               admission_now_ns >= candidate->valid_from_ns &&
2471:               admission_now_ns <= candidate->valid_until_ns &&
2472:               admission_now_ns < candidate->declared_end_ns &&
2473:               measured_state && measured_state->state.finite() &&
2474:               measured_state->state.localization_epoch == candidate->localization_epoch &&
2475:               measured_state->state.world_frame_id == planning_frame_ &&
2476:               measured_state->state.body_frame_id == body_frame_id_ &&
2477:               navigation_contracts::evaluateExecutionStateFreshness(
2478:                   admission_now_ns, measured_state->state.source_stamp_ns,
2479:                   navigation_common::steadyClockNowNanoseconds(), measured_state->state.receive_stamp_ns,
2480:                   data_freshness_window_s_).valid() &&
2481:               navigation_execution::classifyTimestampFreshness(
2482:                   admission_now_ns, candidate->world_identity.observation_stamp_ns,
2483:                   maximum_world_age_ns) == navigation_execution::TimestampFreshness::VALID;
2484:         })
2485:       : navigation_execution::CommitDecision::kPredecessorAdvanced;
2486:   if (decision == navigation_execution::CommitDecision::kCommitted) {
2487:     // Store and runtime authority linearize under the same existing owners.
2488:     // Mapping may publish a same-generation immutable world copy after this
2489:     // point, but cannot observe H with an Episode still describing G.
2490:     command_goal_epoch_.store(token.goal_epoch, std::memory_order_release);
2491:     executing_goal_.swap(prepared_goal);
2492:     execution_episode_.commandCommitted(*candidate);
2493:   }
2494:   return decision;
2495: }
