43: struct CertifiedMainContinuationWindow final {
44:   std::int64_t boundary_stamp_ns{0};
45:   std::int64_t main_end_stamp_ns{0};
46: };
47: 
48: [[nodiscard]] inline std::int64_t minimumMainContinuationReserveNs() noexcept {
49:   constexpr long double reserve_ns = static_cast<long double>(
50:       navigation_planning::PlanningTimingContract::kMinimumMainReserveS) * 1.0e9L;
51:   if (!std::isfinite(reserve_ns) ||
52:       reserve_ns > static_cast<long double>(std::numeric_limits<std::int64_t>::max())) {
53:     return std::numeric_limits<std::int64_t>::max();
54:   }
55:   return static_cast<std::int64_t>(std::llround(reserve_ns));
56: }
57: 
58: [[nodiscard]] inline bool certifiedMainContinuationBoundaryEligible(
59:     const CertifiedMainContinuationBoundaryFacts& facts) noexcept {
60:   if (!facts.pass_through_goal || facts.coincident_terminal_stop ||
61:       facts.trajectory_finished ||
62:       !facts.has_boundary_event || !facts.has_boundary_constraint ||
63:       facts.candidate_localization_epoch == 0U ||
64:       facts.candidate_localization_epoch != facts.expected_localization_epoch ||
65:       facts.candidate_goal_epoch == 0U ||
66:       facts.candidate_goal_epoch != facts.expected_goal_epoch ||
67:       facts.candidate_request_id == 0U ||
68:       facts.candidate_request_id != facts.expected_request_id ||
69:       facts.boundary_kind != navigation_planning::RouteBoundaryEventKind::kPassThrough ||
70:       facts.boundary_role != navigation_planning::CandidateRole::kMain ||
71:       facts.boundary_junction_index != facts.expected_junction_index ||
72:       facts.constraint_junction_index != facts.expected_junction_index ||
73:       facts.boundary_stamp_ns <= 0 ||
74:       facts.declared_end_ns <= facts.declared_start_ns ||
75:       facts.boundary_stamp_ns < facts.declared_start_ns ||
76:       facts.boundary_stamp_ns >= facts.declared_end_ns) {
77:     return false;
78:   }
79:   const auto boundary_offset_ns = facts.boundary_stamp_ns - facts.declared_start_ns;
80:   const auto main_reserve_ns = minimumMainContinuationReserveNs();
81:   return facts.main_interval_begin_ns >= 0 &&
82:          facts.main_interval_end_ns > facts.main_interval_begin_ns &&
83:          boundary_offset_ns >= facts.main_interval_begin_ns &&
84:          boundary_offset_ns < facts.main_interval_end_ns &&
85:          facts.main_interval_end_ns - boundary_offset_ns >= main_reserve_ns;
86: }
87: 
88: [[nodiscard]] inline bool certifiedMainContinuationHandoffReady(
89:     const CertifiedMainContinuationWindow& window,
90:     const std::int64_t now_ns) noexcept {
91:   if (now_ns <= 0 || window.boundary_stamp_ns <= 0 ||
92:       window.main_end_stamp_ns <= window.boundary_stamp_ns ||
93:       window.main_end_stamp_ns <= now_ns) {
94:     return false;
95:   }
96:   return window.main_end_stamp_ns - now_ns >=
97:       minimumMainContinuationReserveNs();
98: }

