5: struct PlanningTimingContract final {
6:   // These values are product scheduler contracts, not deployment knobs. The
7:   // runtime owns the timers, while this header is the single typed source for
8:   // their cadence and bounded safety windows.
9:   static constexpr double kPlannerPeriodS = 0.10;
10:   static constexpr double kPlannerRateHz = 1.0 / kPlannerPeriodS;
11:   static constexpr double kSolveDeadlineS = 0.08;
12:   static constexpr double kStitchDurationS = 0.40;
13:   static constexpr double kCommitGuardS = 0.02;
14:   static constexpr double kMinimumMainReserveS =
15:       kSolveDeadlineS + kStitchDurationS + kPlannerPeriodS + kCommitGuardS;
16:   static constexpr double kUrgentBaselineThresholdS = 1.0;
17:   static constexpr double kCommandPeriodS = 0.02;
18:   static constexpr double kCommandRateHz = 1.0 / kCommandPeriodS;
19:   static constexpr double kCommandStreamTimeoutS = 0.10;
20:   static constexpr double kExternalModeStateAgeS = 0.20;
21:   static constexpr double kSnapshotPeriodS = 0.10;
22:   static constexpr double kLocalWindowM = 20.0;
23:   static constexpr double kInitialHoldTimeoutS = 5.0;
24:   static constexpr double kStoppedRecoveryTimeoutS = 5.0;
25:   static constexpr double kStationarySpeedMps = 0.15;
26: };
27: 
