29:     PlanningTimingContract::kMinimumMainReserveS ==
30:     PlanningTimingContract::kSolveDeadlineS +
31:         PlanningTimingContract::kStitchDurationS +
32:         PlanningTimingContract::kPlannerPeriodS +
33:         PlanningTimingContract::kCommitGuardS);
