247: void MissionController::onNativeTrajectoryReady() {
248:   std::lock_guard<std::mutex> lock(mutex_);
249:   if (state_ == MissionControllerState::Idle ||
250:       state_ == MissionControllerState::Complete ||
251:       state_ == MissionControllerState::Failed) {
252:     return;
253:   }
254:   checkpoint_valid_ = true;
255:   trajectory_ready_ = true;
256:   // A terminal BACKUP can be the only certified command that holds the
257:   // active STOP waypoint. Do not let a later generic readiness callback erase
258:   // that measured-settling contract before the vehicle is slow enough.
259:   // The pending latch is cleared by update() after measured settling, or by
260:   // a new waypoint transition.
261:   const bool active_terminal_stop =
262:       active_waypoint_index_ < mission_.waypoints.size() &&
263:       mission_.waypoints[active_waypoint_index_].behavior ==
264:           MissionWaypoint::Behavior::Stop;
265:   if (!active_terminal_stop || !terminal_hold_pending_) {
266:     terminal_hold_pending_ = false;
267:   }
268: }
