270: void MissionController::onNativeSafetyTrajectoryObserved() {
271:   std::lock_guard<std::mutex> lock(mutex_);
272:   if (state_ == MissionControllerState::Idle ||
273:       state_ == MissionControllerState::Complete ||
274:       state_ == MissionControllerState::Failed) {
275:     return;
276:   }
277:   // BACKUP/EMERGENCY owns the current command until a certified stop. It may
278:   // not be used as the nominal trajectory-ready witness for pass-through
279:   // progress. Keep terminal_hold_pending_ unchanged: a terminal STOP still
280:   // needs its own bounded hold contract.
281:   trajectory_ready_ = false;
282:   checkpoint_valid_ = true;
