285: void MissionController::onNativeTerminalHoldObserved() {
286:   std::lock_guard<std::mutex> lock(mutex_);
287:   if (state_ == MissionControllerState::Idle ||
288:       state_ == MissionControllerState::Complete ||
289:       state_ == MissionControllerState::Failed ||
290:       active_waypoint_index_ >= mission_.waypoints.size()) {
291:     return;
292:   }
293: 
294:   const auto& waypoint = mission_.waypoints[active_waypoint_index_];
295:   if (waypoint.behavior == MissionWaypoint::Behavior::Stop) {
296:     terminal_hold_pending_ = true;
297:     // A terminal safety suffix is not nominal readiness for a pass-through
298:     // checkpoint, but it is the certified command that owns this STOP
299:     // endpoint. Keep the readiness witness so update() can enter the normal
300:     // measured confirmation window when the speed gate settles.
301:     trajectory_ready_ = true;
302:     checkpoint_valid_ = true;
303:     return;
304:   }
305:   if (navigation_mission::passThroughNextWaypointIsCoincidentStop(
306:           route_progress_.snapshot(
307:               mission_.id, mission_.frame, 1U, request_id_,
308:               active_waypoint_index_))) {
309:     // The active pass-through checkpoint is still accepted by the normal
310:     // measured pass-through path, but the following STOP owns the hold. Do
311:     // not request an outgoing velocity for the zero-length boundary.
312:     terminal_hold_pending_ = true;
313:     // onNativeSafetyTrajectoryObserved() deliberately clears generic
314:     // readiness while BACKUP owns the command. Restore readiness only for
315:     // this exact terminal witness so update() can perform the measured
316:     // pass-through acceptance and publish the following STOP goal.
317:     trajectory_ready_ = true;
318:     checkpoint_valid_ = true;
319:     return;
320:   }
321:   if (active_waypoint_index_ == 0U ||
322:       active_waypoint_index_ + 1U >= mission_.waypoints.size()) {
323:     return;
324:   }
325:   const auto& previous = mission_.waypoints[active_waypoint_index_ - 1U];
326:   const auto& next = mission_.waypoints[active_waypoint_index_ + 1U];
327:   const auto incoming = waypoint.position_enu - previous.position_enu;
328:   const auto outgoing = next.position_enu - waypoint.position_enu;
329:   if (!incoming.allFinite() || !outgoing.allFinite() || incoming.norm() <= 1e-6 ||
330:       outgoing.norm() <= 1e-6) {
331:     return;
332:   }
333:   // Match passThroughCornerReady(): a genuine turn must settle before the
334:   // next mission request is allowed to change the velocity direction.
335:   if (incoming.normalized().dot(outgoing.normalized()) <= 0.7) {
336:     terminal_hold_pending_ = true;
337:   }
338: }
