340: MissionControllerEvent MissionController::update(
341:     double now_s, const std::optional<Eigen::Vector3d>& position, bool airborne,
342:     const std::optional<Eigen::Vector3d>& velocity,
343:     const std::optional<CertifiedContinuation>& continuation,
344:     const bool certified_suffix_stop) {
345:   std::lock_guard<std::mutex> lock(mutex_);
346:   if (!std::isfinite(now_s) || state_ == MissionControllerState::Idle ||
347:       state_ == MissionControllerState::Complete || state_ == MissionControllerState::Failed) {
348:     return {};
349:   }
350: 
351:   if (pending_position_control_) {
352:     pending_position_control_ = false;
353:     state_ = MissionControllerState::Paused;
354:     return {MissionControllerEvent::Type::RequestPositionControl, active_waypoint_index_,
355:             request_id_};
356:   }
357: 
358:   if (state_ == MissionControllerState::WaitingForAirborne) {
359:     if (!airborne) return {};
360:     state_ = MissionControllerState::ExecutingWaypoint;
361:   }
362: 
363:   // Keep the last valid mission-update sample for pass-through crossing
364:   // detection. The local copy is deliberately captured before replacing the
365:   // sample so a single update can certify the measured segment that crossed a
366:   // waypoint acceptance ball.
367:   const auto previous_position = previous_position_;
368:   const double previous_position_time_s = previous_position_time_s_;
369:   if (position.has_value() && position->allFinite()) {
370:     previous_position_ = *position;
371:     previous_position_time_s_ = now_s;
372:   }
373: 
374:   if (state_ == MissionControllerState::Braking) {
375:     const bool stopped = velocity.has_value() && velocity->allFinite() &&
376:                          velocity->norm() <= kSafetyStopSpeedMps;
377:     const bool braking_complete = !braking_end_time_s_.has_value() ||
378:                                   now_s >= *braking_end_time_s_;
379:     const auto& braking_waypoint = mission_.waypoints[active_waypoint_index_];
380:     const bool pass_through =
381:         braking_waypoint.behavior == MissionWaypoint::Behavior::PassThrough;
382:     const bool inside_acceptance = position.has_value() && position->allFinite() &&
383:                                    (*position - braking_waypoint.position_enu).norm() <=
384:                                        braking_waypoint.acceptance_radius_m;
385:     if (stopped && braking_complete) {
386:       // A safety trajectory can be selected at the end of a short local
387:       // horizon even though a pass-through waypoint has already been reached.
388:       // Treat that as waypoint acceptance once the vehicle is actually slow,
389:       // rather than handing the whole mission to POSCTL.  Stop waypoints keep
390:       // the fail-closed handover behavior below.
391:       if (pass_through && inside_acceptance) {
392:         const double acceptance_error =
393:             (*position - braking_waypoint.position_enu).norm();
394:         const double acceptance_speed = velocity->norm();
395:         ++active_waypoint_index_;
396:         if (active_waypoint_index_ >= mission_.waypoints.size()) {
397:           state_ = MissionControllerState::Complete;
398:           checkpoint_valid_ = false;
399:           MissionControllerEvent event{MissionControllerEvent::Type::Complete,
400:                                        active_waypoint_index_ - 1U, request_id_};
401:           event.waypoint_accepted = true;
402:           event.accepted_waypoint_index = active_waypoint_index_ - 1U;
403:           event.acceptance_position_error_m = acceptance_error;
404:           event.acceptance_speed_mps = acceptance_speed;
405:           return event;
406:         }
407:         state_ = MissionControllerState::ExecutingWaypoint;
408:         trajectory_ready_ = false;
409:         arrival_start_time_s_.reset();
410:         next_goal_time_s_ = std::numeric_limits<double>::infinity();

410:         next_goal_time_s_ = std::numeric_limits<double>::infinity();
411:         if (!advanceRequestId()) {
412:           state_ = MissionControllerState::Failed;
413:           return {MissionControllerEvent::Type::Failure, active_waypoint_index_, request_id_};
414:         }
415:         braking_start_time_s_.reset();
416:         braking_end_time_s_.reset();
417:         stopped_start_time_s_.reset();
418:         MissionControllerEvent event{MissionControllerEvent::Type::PublishGoal,
419:                                      active_waypoint_index_, request_id_};
420:         event.waypoint_accepted = true;
421:         event.accepted_waypoint_index = active_waypoint_index_ - 1U;
