436:       }
437:     } else {
438:       stopped_start_time_s_.reset();
439:     }
440:     if (!pass_through && braking_start_time_s_.has_value() &&
441:         now_s - *braking_start_time_s_ >= kSafetyStopTimeoutS) {
442:       state_ = MissionControllerState::Paused;
443:       return {MissionControllerEvent::Type::RequestPositionControl,
444:               active_waypoint_index_, request_id_};
445:     }
446:     return {};
447:   }
448: 
449:   if (state_ == MissionControllerState::Paused) return {};
450: 
451:   const auto& waypoint = mission_.waypoints[active_waypoint_index_];
452:   if (position.has_value()) {
453:     (void)route_progress_.update(*position);
454:   }
455:   const auto insideAcceptance = [&]() {
456:     return position.has_value() &&
457:            route_progress_.insideAcceptance(active_waypoint_index_, *position);
458:   };
459:   // A pass-through waypoint is still a mission waypoint, not a planner
460:   // horizon marker. Advance only from measured positions: either the current
461:   // sample is inside the acceptance ball, or two recent measured samples form
462:   // a forward route-ordered segment that intersects that ball. The latter is
463:   // required at cruise speed because a 50 ms mission timer can otherwise skip
464:   // a sub-metre ball between samples.
465:   const auto passThroughAcceptanceError = [&]() -> std::optional<double> {
466:     if (!position.has_value() || !position->allFinite() ||
467:         active_waypoint_index_ >= mission_.waypoints.size()) {
468:       return std::nullopt;
469:     }
470:     const double sample_gap_s = previous_position.has_value() &&
471:                                     std::isfinite(previous_position_time_s) &&
472:                                     now_s >= previous_position_time_s
473:         ? now_s - previous_position_time_s
474:         : std::numeric_limits<double>::quiet_NaN();
475:     return route_progress_.measuredWaypointCrossingError(
476:         active_waypoint_index_, *position, previous_position, sample_gap_s,
477:         kMaximumPassThroughSampleGapS);
478:   };
479:   const auto passThroughAcceptance = [&]() {
480:     return passThroughAcceptanceError().has_value();
481:   };
482:   const auto slowEnough = [&]() {
483:     // Waypoint completion is only valid with a measured, finite velocity
484:     // sample. Missing velocity must not turn a fly-through into an arrival.
485:     return velocity.has_value() && velocity->allFinite() &&
486:            velocity->norm() <= mission_.control.acceptance_speed_mps;
487:   };
488:   const auto passThroughCornerReady = [&]() {
489:     // Position acceptance is still measured and velocity must be finite. The
490:     // planner owns the incoming leg up to this boundary; the next hot-replan
491:     // owns the outgoing turn. Requiring outgoing velocity alignment here
492:     // couples mission progress to one MINCO endpoint and can force a braking
493:     // stop exactly at a sharp corner.
494:     if (!velocity.has_value() || !velocity->allFinite()) return false;
495:     return true;
496:   };
497: 
498:   if (state_ == MissionControllerState::ExecutingWaypoint) {
499:     const bool pass_through = waypoint.behavior == MissionWaypoint::Behavior::PassThrough;
500:     const bool coincident_terminal_stop = pass_through &&
501:         navigation_mission::passThroughNextWaypointIsCoincidentStop(
502:             route_progress_.snapshot(
503:                 mission_.id, mission_.frame, 1U, request_id_,
504:                 active_waypoint_index_));
505:     // Crossing order disambiguates PASS_THROUGH on a self-overlapping route.
506:     // STOP instead requires the current measured position inside its ball;
507:     // projecting a settled endpoint onto an earlier, closer segment must not
508:     // prevent the unchanged measured-speed and confirmation gates below.
509:     const bool inside = pass_through ? passThroughAcceptance() : insideAcceptance();
510:     // Only the initial pass-through checkpoint may be accepted before the
511:     // first native trajectory is acknowledged.  This is the takeoff/mission
512:     // handoff exception for a waypoint that is already inside the measured
513:     // acceptance ball.  Once the route has advanced, trajectory_ready_ is a
514:     // handoff certificate for the *current* waypoint: allowing a later
515:     // pass-through to bypass it can advance MissionController while PX4 is
516:     // still executing the previous waypoint's certified bundle.
517:     const bool immediate_pass_through =
518:         pass_through && active_waypoint_index_ == 0U && request_id_ == 1U && inside &&
519:         slowEnough();
520:     const bool acceptance_ready = pass_through ? passThroughCornerReady() : slowEnough();
521:     // Capture this before the coincident PASS/STOP hold block clears its
522:     // pending marker at a measured stop. The captured readiness is the
523:     // terminal MAIN witness for the same update that accepts PASS.
524:     const bool coincident_terminal_hold_ready = pass_through &&
525:         coincident_terminal_stop && terminal_hold_pending_ && trajectory_ready_;
526:     if (terminal_hold_pending_ && !pass_through) {
527:       // A terminal STOP requires a continuous measured confirmation window,
528:       // not a single low-speed sample. Keep the certified endpoint hold while
529:       // either position or speed temporarily leaves the gate, and restart
530:       // the confirmation timer. This prevents a brief speed dip from
531:       // releasing the hold and allowing a moving replan before the vehicle is
532:       // actually settled.
533:       if (!inside || !acceptance_ready) {
534:         arrival_start_time_s_.reset();
535:         return {};
536:       }
537:       if (!arrival_start_time_s_.has_value()) {
538:         arrival_start_time_s_ = now_s;
539:       }
540:       if (now_s - *arrival_start_time_s_ >= mission_.control.acceptance_confirmation_s) {
541:         terminal_hold_pending_ = false;
542:         state_ = MissionControllerState::Holding;
543:         hold_start_time_s_ = now_s;
544:       }
545:       return {};
546:     }
547:     if (terminal_hold_pending_) {
548:       // A certified terminal MAIN sample already supplies a position hold.
549:       // While the vehicle is inside the active acceptance ball but still
550:       // moving, keep that hold and wait for measured settling. Re-publishing
551:       // the same goal here would clear the hold and recreate the oscillation
552:       // at a corner. If the vehicle has not yet entered the ball, the same
553:       // bounded hold is still safe. A later generic readiness callback cannot
554:       // clear this latch while the active waypoint is a STOP; only measured
555:       // settling or a waypoint transition may release it.
556:       // A coincident PASS_THROUGH/STOP boundary is owned by the following
557:       // STOP. Do not publish that STOP goal while the vehicle is still
558:       // moving through the shared acceptance ball; runtime may still be
559:       // draining the certified suffix and cannot safely replace its identity
560:       // until the measured stop boundary.
561:       const bool terminal_hold_ready = coincident_terminal_stop
562:           ? slowEnough() : acceptance_ready;
563:       if (inside && terminal_hold_ready) {
564:         terminal_hold_pending_ = false;
565:       } else {
566:         return {};
567:       }
568:     }
569:     const bool certified_main_continuation = pass_through && continuation.has_value() &&
570:         continuation->valid() && continuation->mission_id == mission_.id &&
571:         continuation->waypoint_index == active_waypoint_index_ &&
572:         continuation->request_id == request_id_;
573:     // PASS_THROUGH requires measured crossing plus the current accepted MAIN
574:     // command witness. Generic readiness remains for STOP/legacy hold paths.
575:     const bool progression_ready = pass_through
576:         ? (certified_main_continuation || certified_suffix_stop ||
577:            coincident_terminal_hold_ready || immediate_pass_through)
578:         : trajectory_ready_;
579:     if (progression_ready && inside && acceptance_ready) {
580:       if (pass_through) {
581:         const auto acceptance_error = passThroughAcceptanceError();
582:         if (!acceptance_error.has_value() || !position.has_value() ||
583:             !velocity.has_value() || !velocity->allFinite()) {
584:           return {};
585:         }
586:         const double acceptance_speed = velocity->norm();
587:         ++active_waypoint_index_;
588:         if (active_waypoint_index_ >= mission_.waypoints.size()) {
589:           state_ = MissionControllerState::Complete;
590:           checkpoint_valid_ = false;
591:           MissionControllerEvent event{MissionControllerEvent::Type::Complete,
592:                                        active_waypoint_index_ - 1U, request_id_};
593:           event.waypoint_accepted = true;
594:           event.accepted_waypoint_index = active_waypoint_index_ - 1U;
595:           event.acceptance_position_error_m = *acceptance_error;
596:           event.acceptance_speed_mps = acceptance_speed;
597:           return event;
598:         }
599:         state_ = MissionControllerState::ExecutingWaypoint;
600:         trajectory_ready_ = false;
601:         arrival_start_time_s_.reset();
602:         next_goal_time_s_ = std::numeric_limits<double>::infinity();
603:         if (!advanceRequestId()) {
604:           state_ = MissionControllerState::Failed;
605:           return {MissionControllerEvent::Type::Failure, active_waypoint_index_, request_id_};
606:         }
607:         MissionControllerEvent event{MissionControllerEvent::Type::PublishGoal,
608:                                      active_waypoint_index_, request_id_};
609:         event.waypoint_accepted = true;
610:         event.accepted_waypoint_index = active_waypoint_index_ - 1U;
611:         event.acceptance_position_error_m = *acceptance_error;
612:         event.acceptance_speed_mps = acceptance_speed;
613:         return event;
614:       }
615:       if (!arrival_start_time_s_.has_value()) arrival_start_time_s_ = now_s;
616:       if (now_s - *arrival_start_time_s_ >= mission_.control.acceptance_confirmation_s) {
617:         state_ = MissionControllerState::Holding;
618:         hold_start_time_s_ = now_s;
619:         return {};
620:       }
621:     } else {
622:       arrival_start_time_s_.reset();
623:     }
624:     if (now_s >= next_goal_time_s_) {
625:       next_goal_time_s_ = std::numeric_limits<double>::infinity();
626:       trajectory_ready_ = false;
627:       if (!advanceRequestId()) {
628:         state_ = MissionControllerState::Failed;
629:         return {MissionControllerEvent::Type::Failure, active_waypoint_index_, request_id_};
630:       }
631:       return {MissionControllerEvent::Type::PublishGoal, active_waypoint_index_, request_id_};
632:     }
633:     return {};
634:   }
635: 
636:   if (state_ == MissionControllerState::Holding) {
637:     if (!insideAcceptance()) {
638:       state_ = MissionControllerState::ExecutingWaypoint;
639:       trajectory_ready_ = false;
640:       arrival_start_time_s_.reset();
641:       next_goal_time_s_ = std::numeric_limits<double>::infinity();
642:       if (!advanceRequestId()) {
643:         state_ = MissionControllerState::Failed;
644:         return {MissionControllerEvent::Type::Failure, active_waypoint_index_, request_id_};
645:       }
646:       return {MissionControllerEvent::Type::PublishGoal, active_waypoint_index_, request_id_};
647:     }
648:     if (!slowEnough()) {
649:       // Keep the certified position hold while the vehicle is still inside
650:       // the acceptance ball. A single noisy/overshooting velocity sample must
651:       // restart the measured hold timer, not publish the same goal again: the
652:       // latter sends the planner back into a stop/replan loop at a waypoint.
653:       hold_start_time_s_ = now_s;
654:       return {};
655:     }
656:     if (now_s - hold_start_time_s_ >= waypoint.hold_s) {
657:       const double acceptance_error = (*position - waypoint.position_enu).norm();
658:       const double acceptance_speed = velocity->norm();
659:       ++active_waypoint_index_;
660:       if (active_waypoint_index_ >= mission_.waypoints.size()) {
661:         state_ = MissionControllerState::Complete;
662:         checkpoint_valid_ = false;
663:         MissionControllerEvent event{MissionControllerEvent::Type::Complete,
664:                                      active_waypoint_index_ - 1U, request_id_};
665:         event.waypoint_accepted = true;
666:         event.accepted_waypoint_index = active_waypoint_index_ - 1U;
667:         event.acceptance_position_error_m = acceptance_error;
668:         event.acceptance_speed_mps = acceptance_speed;
669:         return event;
670:       }
671:       state_ = MissionControllerState::ExecutingWaypoint;
672:       trajectory_ready_ = false;
673:       arrival_start_time_s_.reset();
674:       next_goal_time_s_ = std::numeric_limits<double>::infinity();
675:       if (!advanceRequestId()) {
676:         state_ = MissionControllerState::Failed;
677:         return {MissionControllerEvent::Type::Failure, active_waypoint_index_, request_id_};
678:       }
679:       MissionControllerEvent event{MissionControllerEvent::Type::PublishGoal,
680:                                    active_waypoint_index_, request_id_};
681:       event.waypoint_accepted = true;
682:       event.accepted_waypoint_index = active_waypoint_index_ - 1U;
683:       event.acceptance_position_error_m = acceptance_error;
684:       event.acceptance_speed_mps = acceptance_speed;
685:       return event;
686:     }
687:   }
688:   return {};
689: }
