422: bool RouteProgress::insideAcceptance(const std::size_t waypoint_index,
423:                                      const Eigen::Vector3d& position) const noexcept {
424:   if (waypoint_index >= waypoints_.size() || !position.allFinite()) return false;
425:   const double distance_m = (position - waypoints_[waypoint_index].position_enu).norm();
426:   return std::isfinite(distance_m) &&
427:          distance_m <= waypoints_[waypoint_index].acceptance_radius_m;
428: }
429: 
430: std::optional<double> RouteProgress::measuredWaypointCrossingError(
431:     const std::size_t waypoint_index, const Eigen::Vector3d& current_position,
432:     const std::optional<Eigen::Vector3d>& previous_position,
433:     const double sample_gap_s, const double maximum_sample_gap_s) const noexcept {
434:   if (waypoint_index >= waypoints_.size() || !current_position.allFinite()) {
435:     return std::nullopt;
436:   }
437:   const auto& waypoint = waypoints_[waypoint_index];
438:   const auto ordered_projection = [&]() -> std::optional<RouteProjection> {
439:     auto projection = project(current_position);
440:     if (!projection.valid) return std::nullopt;
441: 
442:     // update() resolves an exact self-overlap using the previous monotonic
443:     // arc.  Preserve that branch choice when it is at least as close as the
444:     // stateless projection; otherwise this method remains safe for callers
445:     // that use it without first updating route progress.
446:     const double state_point_distance_m =
447:         (state_.projection.point - current_position).norm();
448:     if (state_.valid && state_.projection.valid &&
449:         std::isfinite(state_point_distance_m) &&
450:         state_point_distance_m <= projection.lateral_error_m + 1.0e-6 &&
451:         state_.projection.lateral_error_m <= projection.lateral_error_m +
452:             1.0e-6) {
453:       projection = state_.projection;
454:     }
455:     if (segments_.empty()) return projection;
456:     if (projection.segment_index >= segments_.size()) return std::nullopt;
457:     const auto& segment = segments_[projection.segment_index];
458:     const double waypoint_arc_m = waypoint_arc_lengths_[waypoint_index];
459:     constexpr double kWaypointArcToleranceM = 1.0e-6;
460:     if (std::abs(segment.start_arc_m - waypoint_arc_m) > kWaypointArcToleranceM &&
461:         std::abs(segment.end_arc_m - waypoint_arc_m) > kWaypointArcToleranceM) {
462:       return std::nullopt;
463:     }
464:     return projection;
465:   };
466:   const double current_error = (current_position - waypoint.position_enu).norm();
467:   if (std::isfinite(current_error) && current_error <= waypoint.acceptance_radius_m) {
468:     if (!ordered_projection().has_value()) return std::nullopt;
469:     return current_error;
470:   }
471:   if (!previous_position.has_value() || !previous_position->allFinite() ||
472:       !std::isfinite(sample_gap_s) || !std::isfinite(maximum_sample_gap_s) ||
473:       sample_gap_s < 0.0 || maximum_sample_gap_s < 0.0 ||
474:       sample_gap_s > maximum_sample_gap_s) {
475:     return std::nullopt;
476:   }
477:   const auto incoming = incomingTangent(waypoint_index);
478:   if (!incoming.has_value()) return std::nullopt;
479:   const Eigen::Vector3d measured_motion = current_position - *previous_position;
480:   if (!measured_motion.allFinite() || measured_motion.dot(*incoming) <= 1.0e-6) {
481:     return std::nullopt;
482:   }
483:   const auto error = segmentDistanceToPoint(
484:       *previous_position, current_position, waypoint.position_enu);
485:   if (!error.has_value() || *error > waypoint.acceptance_radius_m + 1.0e-6) {
486:     return std::nullopt;
487:   }
488:   if (!ordered_projection().has_value()) return std::nullopt;
489:   return error;
490: }
