2630:     {
2631:       std::lock_guard<std::mutex> lock(trajectory_mutex_);
2632:       terminal_recovery_window_open = terminalRecoveryCommandMayBeHeld(
2633:           navigation_command->status ==
2634:               navigation_contracts::msg::NavigationCommand::STATUS_COMPLETED,
2635:           planner_recovery_pending_, now.nanoseconds(), planner_recovery_deadline_ns_);
2636:       terminal_recovery_window_open = terminal_recovery_window_open &&
2637:           plannerRecoveryEpisodeMatchesLocked(*navigation_command);
2638:     }
2639:     const auto receive_ns = [&]() {
2640:       std::lock_guard<std::mutex> lock(trajectory_mutex_);
2641:       return last_command_receive_ns_;
2642:     }();
2643:     if (receive_ns > 0 && now.nanoseconds() >= receive_ns &&
2644:         now.nanoseconds() - receive_ns > stale_after_ns_ &&
2645:         !terminal_recovery_window_open) {
2646:       safetyStopNavigation("planner backend PVA command stale");
2647:       return;
2648:     }
2649:     const auto& command = *navigation_command;
2650:     const auto command_stamp_ns =
2651:         navigation_common::rosTimeToNanoseconds(command.header.stamp).value_or(0);
2652:     if (command_stamp_ns <= 0 || command_stamp_ns > now.nanoseconds() ||
2653:         (now.nanoseconds() >= command_stamp_ns &&
2654:          now.nanoseconds() - command_stamp_ns > stale_after_ns_ &&
2655:          !terminal_recovery_window_open)) {
2656:       safetyStopNavigation("planner backend PVA command timestamp invalid or stale");
2657:       return;
2658:     }
2659:     if (!terminal_recovery_window_open &&
2660:         !navigation_contracts::commandValidAt(command, now.nanoseconds())) {
2661:       safetyStopNavigation("planner backend command validity window expired");
2662:       return;
2663:     }
2664:     const Eigen::Vector3d position_enu{command.position.x, command.position.y,
2665:                                        command.position.z};
2666:     const Eigen::Vector3d velocity_enu{command.velocity.x, command.velocity.y,
2667:                                        command.velocity.z};
2668:     const Eigen::Vector3d acceleration_enu{command.acceleration.x, command.acceleration.y,
2669:                                             command.acceleration.z};
2670:     bool terminal_hold_inside_acceptance = false;
2671:     if (command.status ==
2672:             navigation_contracts::msg::NavigationCommand::STATUS_COMPLETED &&
2673:         (command.role == navigation_contracts::msg::NavigationCommand::ROLE_BACKUP ||
2674:          command.role == navigation_contracts::msg::NavigationCommand::ROLE_MAIN) &&
2675:         !mission_terminal_ && mission_controller_ && odometry.has_value()) {
2676:       const auto waypoint = mission_controller_->activeWaypoint();
2677:       if (!waypoint.has_value()) {
2678:         safetyStopNavigation("completed command has no active waypoint");
2679:         return;
2680:       }
2681:       const auto& point = odometry->pose.pose.position;
2682:       const Eigen::Vector3d measured{point.x, point.y, point.z};
2683:       const Eigen::Vector3d command_position{command.position.x, command.position.y,
2684:                                              command.position.z};
2685:       const bool command_inside_acceptance =
2686:           command_position.allFinite() &&
2687:           (command_position - waypoint->position_enu).norm() <=
2688:               waypoint->acceptance_radius_m;
2689:       const bool measured_inside_acceptance =
2690:           measured.allFinite() &&
2691:           (measured - waypoint->position_enu).norm() <=
2692:               waypoint->acceptance_radius_m;
2693:       if (command.role == navigation_contracts::msg::NavigationCommand::ROLE_BACKUP) {
2694:         terminal_hold_inside_acceptance = measured_inside_acceptance &&
2695:             backupEndpointHoldIsAnchored(
2696:                 command_inside_acceptance, measured.allFinite(),
2697:                 command_position.allFinite(), (measured - command_position).norm(),
2698:                 navigation_contracts::kCommandAnchorErrorLimitM);
2699:       } else {
2700:         terminal_hold_inside_acceptance =
2701:             measured_inside_acceptance && command_inside_acceptance;
2702:       }
2703:     }
2704:     if (command.status ==
2705:         navigation_contracts::msg::NavigationCommand::STATUS_REJECTED) {
2706:       safetyStopNavigation("planner backend planner failed without a valid backup trajectory");
2707:       return;
2708:     }
2709:     if (command.status ==
2710:         navigation_contracts::msg::NavigationCommand::STATUS_COMPLETED) {
2711:       if (tracking_experiment_.velocity_only_enabled) {
2712:         requestVelocityOnlyHold("terminal command requires native PX4 Hold");
2713:         return;
2714:       }
2715:       if (!publishPositionHold(position_enu)) {
2716:         safetyStopNavigation("completed command position is not representable by PX4");
2717:         return;
2718:       }
2719:       if ((command.role == navigation_contracts::msg::NavigationCommand::ROLE_BACKUP ||
2720:            command.role == navigation_contracts::msg::NavigationCommand::ROLE_MAIN) &&
2721:           !terminal_hold_inside_acceptance && !mission_terminal_) {
2722:         // The command publisher and PX4 setpoint callback are independent
2723:         // executor paths. A replacement PlanFromRest command can therefore
2724:         // arrive immediately after this completed sample. Keep publishing
2725:         // the exact endpoint hold for one bounded recovery window; the mission
2726:         // timer performs the fail-closed handover if no replacement arrives.
2727:         bool recovery_deadline_invalid = false;
2728:         {
2729:           std::lock_guard<std::mutex> lock(trajectory_mutex_);
2730:           if (!planner_recovery_pending_) {
2731:             const auto deadline =
2732:                 checkedTimestampAdd(now.nanoseconds(), planner_recovery_wait_timeout_ns_);
2733:             if (!deadline) {
2734:               recovery_deadline_invalid = true;
2735:             } else {
2736:               planner_recovery_pending_ = true;
2737:               planner_recovery_deadline_ns_ = *deadline;
2738:               rememberPlannerRecoveryEpisodeLocked(*navigation_command);
2739:               RCLCPP_WARN(node().get_logger(),
2740:                           "planner backend terminal endpoint reached; holding for bounded "
2741:                           "planner recovery window %.3f s",
2742:                           planner_recovery_wait_timeout_s_);
2743:             }
2744:           }
2745:         }
2746:         if (recovery_deadline_invalid) {
2747:           safetyStopNavigation("planner recovery deadline is not representable");
2748:         }
2749:         return;
2750:       }
2751:       std::lock_guard<std::mutex> lock(trajectory_mutex_);
2752:       last_setpoint_time_ = now;
2753:       return;
2754:     }
2755:     if (tracking_experiment_.velocity_only_enabled) {
2756:       if (!velocity_only_snapshot.has_value() ||
2757:           !publishVelocityOnlySetpoint(command, *velocity_only_snapshot, now)) {
2758:         std::string reason;
2759:         {
2760:           std::lock_guard<std::mutex> lock(trajectory_mutex_);
2761:           reason = velocity_only_last_reason_.empty()
2762:               ? "velocity-only setpoint unavailable" : velocity_only_last_reason_;
2763:         }
2764:         requestVelocityOnlyHold(reason.c_str());
2765:       }
2766:       return;
2767:     }
2768:     const auto position_ned = lioPositionToPx4Ned(position_enu);
2769:     const auto velocity_ned = checkedEnuToNed(velocity_enu);
2770:     const auto acceleration_ned = checkedEnuToNed(acceleration_enu);
2771:     if (!position_ned || !velocity_ned || !acceleration_ned ||
2772:         !floatRepresentable(command.yaw) || !floatRepresentable(command.yaw_rate)) {
2773:       safetyStopNavigation("planner backend PVA command is not representable by PX4");
2774:       return;
2775:     }
2776:     px4_ros2::TrajectorySetpoint setpoint;
2777:     setpoint.withPosition(*position_ned)
2778:         .withVelocity(*velocity_ned)
2779:         .withAcceleration(*acceleration_ned)
2780:         .withYaw(px4_ros2::yawEnuToNed(static_cast<float>(command.yaw)))
2781:         .withYawRate(px4_ros2::yawRateEnuToNed(static_cast<float>(command.yaw_rate)));
2782:     auto trace = makePx4InputTraceRecord(
2783:         navigation_command ? &*navigation_command : nullptr,
2784:         position_ned, velocity_ned, acceleration_ned,
2785:         setpoint.yaw_ned_rad.value_or(NAN), setpoint.yaw_rate_ned_rad_s.value_or(NAN),
2786:         Px4InputTraceBoundary::kTracking, 0, 0,
2787:         trace_velocity_only_reason, trace_velocity_only_limited_count, state_input_trace);
2788:     trace.update_start_ros_ns = node().get_clock()->now().nanoseconds();
2789:     trace.update_start_steady_ns = navigation_common::steadyClockNowNanoseconds();
2790:     trajectory_setpoint_->update(setpoint);
2791:     trace.update_end_ros_ns = node().get_clock()->now().nanoseconds();
2792:     trace.update_end_steady_ns = navigation_common::steadyClockNowNanoseconds();
2793:     enqueuePx4InputTrace(trace);
2794:     {
2795:       std::lock_guard<std::mutex> lock(trajectory_mutex_);
2796:       last_velocity_command_enu_ = velocity_enu;
2797:       last_setpoint_time_ = now;
2798:     }
2799:     return;
2800:   }
