2802:   // A goal publication and its first PVA command are asynchronous. Hold the
2803:   // current position during this bounded acquisition window so the mode does
2804:   // not hand over to PX4 Hold on the same 50 Hz tick that starts planning. Once
2805:   // the window expires, fail closed instead of reusing an older trajectory.
2806:   std::int64_t goal_publish_ns = 0;
2807:   {
2808:     std::lock_guard<std::mutex> lock(trajectory_mutex_);
2809:     goal_publish_ns = last_goal_publish_ns_;
2810:   }
2811:   if (goal_publish_ns > 0 && now.nanoseconds() >= goal_publish_ns &&
2812:       static_cast<double>(now.nanoseconds() - goal_publish_ns) / 1e9 <=
2813:           trajectory_wait_timeout_s_) {
2814:     publishStationary(odometry.has_value()
2815:                           ? std::optional<Eigen::Vector3d>{Eigen::Vector3d{
2816:                                 odometry->pose.pose.position.x,
2817:                                 odometry->pose.pose.position.y,
2818:                                 odometry->pose.pose.position.z}}
2819:                           : std::nullopt);
2820:     std::lock_guard<std::mutex> lock(trajectory_mutex_);
