2931: void NavigationModeExecutor::onDeactivate(DeactivateReason reason) {
2932:   px4_hold_confirmed_ = false;
2933:   hold_handover_pending_ = false;
2934:   hold_handover_in_flight_ = false;
2935:   hold_handover_complete_navigation_failure_ = false;
2936:   hold_handover_attempts_ = 0U;
2937:   hold_handover_next_retry_steady_ns_ = 0;
2938:   RCLCPP_INFO(node_.get_logger(), "Avoidance Mission executor deactivated (%s)",
2939:               reason == DeactivateReason::FailsafeActivated ? "failsafe" : "mode_exit");
2940: }
