89:   void setNow(std::int64_t now_ns) {
90:     ASSERT_EQ(rcl_set_ros_time_override(node_->get_clock()->get_clock_handle(), now_ns), RCL_RET_OK);
91:     ASSERT_EQ(node_->get_clock()->now().nanoseconds(), now_ns);
