94:   builtin_interfaces::msg::Time stamp(std::int64_t ns) const {
95:     return rclcpp::Time(ns, RCL_ROS_TIME);
96:   }
97:   static std::int64_t fixtureStampNanoseconds(
98:       const builtin_interfaces::msg::Time& value) {
99:     // Fixture clocks are small, positive and representable. Use an independent
100:     // integral conversion rather than the producer/receiver contract helper.
101:     return static_cast<std::int64_t>(value.sec) * 1'000'000'000 + value.nanosec;
102:   }
103:   void health(bool valid = true, std::uint64_t epoch = 7U,
104:               std::int64_t source_ns = 0) {
105:     auto message = std::make_shared<Health>();
106:     message->header.frame_id = "lio_odom";
107:     message->header.stamp = stamp(source_ns > 0 ? source_ns : now_ns_);
108:     message->localization_epoch = epoch;
109:     message->state = valid ? Health::TRACKING : Health::DEGRADED;
110:     message->navigation_valid = valid;
111:     message->covariance_valid = valid;
112:     message->observability_valid = valid;
113:     message->correction_fresh = valid;
114:     message->propagation_valid = valid;
115:     message->last_correction_stamp = message->header.stamp;
116:     message->last_propagated_state_stamp = message->header.stamp;
117:     mode_->onEstimatorHealth(message);
118:   }
119:   void odometry(const Eigen::Vector3d& position, std::int64_t source_ns = 0,
120:                 const Eigen::Vector3d& velocity = Eigen::Vector3d{3.49, 0.0, 0.0}) {
121:     auto message = std::make_shared<navigation_contracts::msg::PropagatedOdometry>();
122:     message->localization_epoch = 7U;
123:     message->sequence = ++sequence_;
124:     auto& odom = message->odometry;
125:     odom.header.frame_id = "lio_odom";
126:     odom.header.stamp = stamp(source_ns > 0 ? source_ns : now_ns_);
127:     odom.child_frame_id = "base_link";
128:     odom.pose.pose.position.x = position.x();
129:     odom.pose.pose.position.y = position.y();
130:     odom.pose.pose.position.z = position.z();
131:     odom.pose.pose.orientation.w = 1.0;
132:     odom.twist.twist.linear.x = velocity.x();
133:     odom.twist.twist.linear.y = velocity.y();
134:     odom.twist.twist.linear.z = velocity.z();
135:     mode_->onOdometry(message);
136:   }
137:   std::shared_ptr<Command> completedStopCommand() {
138:     auto message = command(false);
139:     message->goal_epoch = 3U;
140:     message->waypoint_index = static_cast<std::uint32_t>(waypoint());
141:     message->request_id = request();
142:     message->bundle_generation = 9U;
143:     message->status = Command::STATUS_COMPLETED;
144:     message->certified_main_continuation = false;
145:     message->velocity = geometry_msgs::msg::Vector3{};
146:     message->valid_until = stamp(now_ns_ + 100'000'000);
147:     return message;
148:   }
149:   static Eigen::Vector3d inBall() {
150:     return {19.149405286591282, 4.816194674794652, 2.961046013093615};
151:   }
152:   std::shared_ptr<Command> command(bool continuation = true) {
153:     auto message = std::make_shared<Command>();
154:     message->header.frame_id = "lio_odom";
155:     message->header.stamp = stamp(now_ns_);
156:     message->localization_epoch = 7U;
157:     message->goal_epoch = 2U;
158:     message->mission_id = "continuation_window";
159:     message->waypoint_index = 1U;
160:     message->request_id = 2U;
161:     message->world_generation = 2U;
162:     message->world_revision = 1U;
163:     message->world_observation_stamp = stamp(now_ns_);
164:     message->bundle_generation = 8U;
165:     message->sample_id = ++sample_;
166:     message->state_source_stamp = stamp(now_ns_);
167:     message->valid_until = stamp(now_ns_ + 100'000'000);
168:     message->certified_main_continuation = continuation;
169:     message->continuation_boundary_stamp_ns = continuation ? kBoundary : 0U;
170:     message->role = Command::ROLE_MAIN;
171:     message->status = Command::STATUS_READY;
172:     message->trajectory_time_s = static_cast<double>(now_ns_ - 37'612'000'000) / 1e9;
173:     if (mode_->odometry_) message->position = mode_->odometry_->pose.pose.position;
174:     message->velocity.x = 3.49;
175:     return message;
176:   }
177:   std::shared_ptr<Command> commandFromCanonicalMainReserve(
178:       const std::int64_t main_end_ns, const std::int64_t sphere_entry_ns) {
179:     // Synthetic arithmetic for the current 600 ms publisher contract. This
180:     // package has no navigation_planning dependency; keep the test independent
181:     // instead of introducing a runtime/backend dependency or a production gate.
182:     constexpr std::int64_t kSyntheticMainReserveNs = 600'000'000;
183:     auto message = command(false);
184:     const auto command_stamp_ns = fixtureStampNanoseconds(message->header.stamp);
185:     message->certified_main_continuation =
186:         main_end_ns - command_stamp_ns >= kSyntheticMainReserveNs;
187:     message->continuation_boundary_stamp_ns = message->certified_main_continuation
188:         ? static_cast<std::uint64_t>(sphere_entry_ns) : 0U;
189:     const Eigen::Vector3d velocity =
190:         3.49 * Eigen::Vector3d{20.0, 5.0, 0.0}.normalized();
191:     message->velocity.x = velocity.x();
192:     message->velocity.y = velocity.y();
193:     message->velocity.z = velocity.z();
194:     return message;
195:   }
196:   static Eigen::Vector3d syntheticSphereEntryPosition(
197:       const std::int64_t sample_ns, const std::int64_t sphere_entry_ns) {
198:     const Eigen::Vector3d incoming = Eigen::Vector3d{20.0, 5.0, 0.0}.normalized();
199:     const double elapsed_s = static_cast<double>(sample_ns - sphere_entry_ns) / 1.0e9;
200:     return Eigen::Vector3d{20.0, 5.0, 3.0} +
201:         (3.49 * elapsed_s - 0.9) * incoming;
202:   }
203:   void admit(const std::shared_ptr<Command>& message) {
204:     mode_->onNavigationCommand(message);
205:   }
206:   void timerTick() { mode_->updateMission(); }
207:   std::size_t waypoint() const { return mode_->mission_controller_->activeWaypointIndex(); }
208:   std::uint64_t request() const { return mode_->mission_controller_->activeRequestId(); }
209:   std::uint64_t acceptedSample() const {
210:     return mode_->navigation_command_ ? mode_->navigation_command_->sample_id : 0U;
211:   }
212:   bool failed() const { return mode_->failure_reported_; }
213:   bool missionCompleted() const { return mode_->mission_complete_published_; }
214:   bool holding() const { return mode_->mission_controller_->holding(); }
215:   void requestHold() { mode_->safetyStopNavigation("progression fixture handover"); }
216:   void expectSerializedCallbacks() const {
217:     const auto group = node_->get_node_base_interface()->get_default_callback_group();
218:     EXPECT_EQ(group->type(), rclcpp::CallbackGroupType::MutuallyExclusive);
219:     EXPECT_EQ(group->find_subscription_ptrs_if([this](const auto& subscription) {
220:       return subscription == mode_->navigation_command_subscription_;
221:     }), mode_->navigation_command_subscription_);
222:     EXPECT_EQ(group->find_timer_ptrs_if([this](const auto& timer) {
223:       return timer == mode_->mission_timer_;
224:     }), mode_->mission_timer_);
225:   }
