280: TEST_F(NavigationModeProgressionTest,
281:        ExactSphereEntryReserveFalseReplacementBeforeTimerBlocksProgression) {
282:   // Map conceptual entry=10.000 s and MAIN end=10.600 s onto fixture clocks.
283:   // These callback phases are synthetic schedules, not measured flight bounds.
284:   constexpr auto entry_ns = kCrossing;
285:   constexpr auto main_end_ns = entry_ns + 600'000'000;
286:   const Eigen::Vector3d velocity =
287:       3.49 * Eigen::Vector3d{20.0, 5.0, 0.0}.normalized();
288:   setNow(entry_ns - 10'000'000);
