318: TEST_F(NavigationModeProgressionTest,
319:        ExactSphereEntryReserveTimerBeforeFalseReplacementConsumesLease) {
320:   // Same canonical geometry/reserve as the paired test; only consumption order
321:   // changes. The receiver must not invent a 600 ms-at-use gate: its accepted
322:   // true witness remains consumable during the existing 100 ms command lease.
323:   constexpr auto entry_ns = kCrossing;
324:   constexpr auto main_end_ns = entry_ns + 600'000'000;
325:   const Eigen::Vector3d velocity =
326:       3.49 * Eigen::Vector3d{20.0, 5.0, 0.0}.normalized();
327:   setNow(entry_ns - 10'000'000);
