339:   const auto command_stamp_ns = fixtureStampNanoseconds(before_entry->header.stamp);
340:   const auto valid_until_ns = fixtureStampNanoseconds(before_entry->valid_until);
341:   ASSERT_GT(command_stamp_ns, 0);
342:   ASSERT_LE(command_stamp_ns, now_ns_);
343:   ASSERT_GT(valid_until_ns, command_stamp_ns);
344:   ASSERT_LE(now_ns_, valid_until_ns);
345:   ASSERT_LT(main_end_ns - now_ns_, 600'000'000);
