353:   const auto after_entry = commandFromCanonicalMainReserve(main_end_ns, entry_ns);
354:   ASSERT_FALSE(after_entry->certified_main_continuation);
355:   admit(after_entry);  // A retained predecessor cannot advance the next goal.
