15: TEST(Px4InputStateTrace, QueuedSnapshotKeepsItsStateAcrossMutationAndEpochReset) {
16:   using namespace px4_navigation_external_mode;
17:   navigation_common::BoundedSpscQueue<Px4InputTraceRecord, 8U> queue;
18:   Px4InputStateTrace live{7U, 42U, 1'000, 1'010, 2'000, 2'005,
19:                          2'100, 2'110, 1'020, 2'120};
20:   for (const auto boundary : {Px4InputTraceBoundary::kTracking,
21:                               Px4InputTraceBoundary::kVelocityOnly,
22:                               Px4InputTraceBoundary::kVelocityHold,
23:                               Px4InputTraceBoundary::kPositionHold}) {
24:     Px4InputTraceRecord record;
25:     record.boundary = boundary;
26:     record.state_input = live;
27:     ASSERT_TRUE(queue.tryPush(record));
28:   }
29:   live = {};  // Epoch invalidation must not relabel already enqueued records.
30:   live.localization_epoch = 8U;
31:   live.sequence = 1U;
32:   for (int index = 0; index < 4; ++index) {
33:     Px4InputTraceRecord record;
34:     ASSERT_TRUE(queue.tryPop(record));
35:     EXPECT_EQ(record.state_input.localization_epoch, 7U);
36:     EXPECT_EQ(record.state_input.sequence, 42U);
37:     EXPECT_EQ(record.state_input.source_stamp_ros_ns, 1'000);
38:     EXPECT_EQ(record.state_input.callback_enter_steady_ns, 2'000);
39:     EXPECT_EQ(record.state_input.lock_requested_steady_ns, 2'005);
40:     EXPECT_EQ(record.state_input.lock_acquired_steady_ns, 2'100);
41:     EXPECT_EQ(record.state_input.receive_steady_ns, 2'110);
42:     EXPECT_EQ(record.state_input.snapshot_steady_ns, 2'120);
43:   }
44: }
