14: enum class EvidenceSpeedFailure : std::uint8_t {
15:   kNone,
16:   kInvalidInput,
17:   kOutsideRecoveryEnvelope,
18:   kInsufficientSupport,
19:   kStopSynthesisFailed,
20:   kBudgetExhausted,
21: };
22: 
23: struct EvidenceSpeedLimit final {
24:   double speed_mps{0.0};
25:   // Scalar polynomial-hull support proposal only. It does not prove the
26:   // continuation lies inside a world/corridor; the planner runs those
27:   // independent candidate validators before staging.
28:   double support_m{0.0};
29:   // Means a concrete stop polynomial fits this scalar support and caller V/A/J
30:   // limits, not that a command has execution or world-certificate authority.
31:   bool sufficient{false};
32:   EvidenceSpeedFailure failure{EvidenceSpeedFailure::kInvalidInput};
33: };
34: 
35: namespace detail {
36: 
37: inline EvidenceSpeedFailure stopFailureToSpeedFailure(
38:     const StopFailureReason failure) noexcept {
39:   switch (failure) {
40:     case StopFailureReason::kNone:
41:       return EvidenceSpeedFailure::kNone;
42:     case StopFailureReason::kInvalidState:
43:     case StopFailureReason::kInvalidDynamics:
44:       return EvidenceSpeedFailure::kInvalidInput;
45:     case StopFailureReason::kOutsideRecoveryEnvelope:
46:       return EvidenceSpeedFailure::kOutsideRecoveryEnvelope;
47:     case StopFailureReason::kInsufficientSupport:
48:       return EvidenceSpeedFailure::kInsufficientSupport;
49:     case StopFailureReason::kSynthesisFailed:
50:       return EvidenceSpeedFailure::kStopSynthesisFailed;
51:     case StopFailureReason::kBudgetExhausted:
52:       return EvidenceSpeedFailure::kBudgetExhausted;
53:   }
54:   return EvidenceSpeedFailure::kInvalidInput;
55: }
56: 
57: inline double minimumSnapSteadyCruiseSpeedCap(
58:     const double requested_speed_mps, const double maximum_velocity_mps,
59:     const double maximum_acceleration_mps2,
60:     const double maximum_jerk_mps3, const double support_m,
61:     const double sample_traj_dt_s) noexcept {
62:   if (!std::isfinite(requested_speed_mps) || requested_speed_mps <= 0.0 ||
63:       !std::isfinite(maximum_velocity_mps) || maximum_velocity_mps <= 0.0 ||
64:       !std::isfinite(maximum_acceleration_mps2) || maximum_acceleration_mps2 <= 0.0 ||
65:       !std::isfinite(maximum_jerk_mps3) || maximum_jerk_mps3 <= 0.0 ||
66:       !std::isfinite(support_m) || support_m <= 0.0 ||
67:       !std::isfinite(sample_traj_dt_s) || sample_traj_dt_s <= 0.0) {
68:     return 0.0;
69:   }
70:   const long double support = static_cast<long double>(support_m);
71:   const long double floor = 4.0L * static_cast<long double>(sample_traj_dt_s);
72:   const long double acceleration =
73:       static_cast<long double>(maximum_acceleration_mps2);
74:   const long double jerk = static_cast<long double>(maximum_jerk_mps3);
75:   const long double cap = std::min({
76:       static_cast<long double>(requested_speed_mps),
77:       static_cast<long double>(maximum_velocity_mps),
78:       2.0L * support / floor,
79:       std::sqrt(16.0L * acceleration * support / 15.0L),
80:       std::cbrt(2.0L * std::sqrt(3.0L) * jerk * support * support / 5.0L)});
81:   const double result = static_cast<double>(cap);
82:   return std::isfinite(result) && result > 0.0 ? result : 0.0;
83: }
84: 
85: template <typename ShouldAbort>
86: [[nodiscard]] inline EvidenceSpeedLimit evidenceAwareSpeedLimitImpl(
87:     const navigation_math::StatePVAJ& state,
88:     const navigation_planning::DynamicLimits& dynamics,
89:     const std::array<double, 4>& support_m,
90:     const double sample_traj_dt_s,
91:     ShouldAbort&& should_abort) noexcept {
92:   EvidenceSpeedLimit result;
93:   if (!state.allFinite() || !dynamics.valid() ||
94:       !std::isfinite(sample_traj_dt_s) || sample_traj_dt_s <= 0.0) {
95:     return result;
96:   }
97:   result.support_m = std::numeric_limits<double>::infinity();
98:   for (const double support : support_m) {
99:     if (!std::isfinite(support) || support <= 0.0) {
100:       result.support_m = 0.0;
101:       result.failure = EvidenceSpeedFailure::kInsufficientSupport;
102:       return result;
103:     }
104:     result.support_m = std::min(result.support_m, support);
105:   }
106: 
107:   const auto abort_requested = [&]() noexcept {
108:     try {
109:       return static_cast<bool>(should_abort());
110:     } catch (...) {
111:       return true;
112:     }
113:   };
114:   if (abort_requested()) {
115:     result.failure = EvidenceSpeedFailure::kBudgetExhausted;
116:     return result;
117:   }
118: 
119:   // First certify the actual PVAJ boundary under the caller's physical
120:   // recovery model. Reducing desired cruise speed does not reduce current
121:   // measured velocity, acceleration, or jerk.
122:   const auto current_stop = evaluateStopReachabilityWithAbort(
123:       state, dynamics, result.support_m, sample_traj_dt_s, 0.0,
124:       abort_requested);
125:   if (!current_stop.feasible) {
126:     result.failure = stopFailureToSpeedFailure(current_stop.failure);
127:     return result;
128:   }
129: 
130:   const Eigen::Vector3d velocity = state.col(1);
131:   const Eigen::Vector3d direction = velocity.norm() > 1.0e-9
132:       ? velocity.normalized() : Eigen::Vector3d::UnitX();
133:   const double upper = dynamics.intent.requested_cruise_speed_mps;
134:   double candidate_speed = minimumSnapSteadyCruiseSpeedCap(
135:       upper, dynamics.vehicle.maximum_velocity_mps,
136:       dynamics.vehicle.maximum_acceleration_mps2,
137:       dynamics.vehicle.maximum_jerk_mps3, result.support_m,
138:       sample_traj_dt_s);
139:   if (candidate_speed <= 0.0) {
140:     result.failure = EvidenceSpeedFailure::kInsufficientSupport;
141:     return result;
142:   }
143: 
144:   // The proposal is restricted to steady prospective cruise (a=j=0). Its
145:   // closed-form cap is checked by the same production stop polynomial and
146:   // continuous extrema used by BACKUP. Correct only bounded floating-point
147:   // boundary discrepancies; this is not a speed search grid.
148:   constexpr std::size_t kMaximumRoundoffCorrections = 2U;
149:   for (std::size_t correction = 0U;
150:        correction <= kMaximumRoundoffCorrections; ++correction) {
151:     if (abort_requested()) {
152:       result.failure = EvidenceSpeedFailure::kBudgetExhausted;
153:       return result;
154:     }
155:     navigation_math::StatePVAJ candidate_state;
156:     candidate_state.setZero();
157:     candidate_state.col(0) = state.col(0);
158:     candidate_state.col(1) = direction * candidate_speed;
159:     const auto candidate_stop = evaluateStopReachabilityWithAbort(
160:         candidate_state, dynamics, result.support_m, sample_traj_dt_s, 0.0,
161:         abort_requested);
162:     if (candidate_stop.feasible) {
163:       if (abort_requested()) {
164:         result.failure = EvidenceSpeedFailure::kBudgetExhausted;
165:         return result;
166:       }
167:       result.speed_mps = candidate_speed;
168:       result.sufficient = true;
169:       result.failure = EvidenceSpeedFailure::kNone;
170:       return result;
171:     }
172:     if (candidate_stop.failure == StopFailureReason::kBudgetExhausted) {
173:       result.failure = EvidenceSpeedFailure::kBudgetExhausted;
174:       return result;
175:     }
176:     if (candidate_stop.failure == StopFailureReason::kOutsideRecoveryEnvelope) {
177:       result.failure = EvidenceSpeedFailure::kOutsideRecoveryEnvelope;
178:       return result;
179:     } else if (candidate_stop.failure == StopFailureReason::kSynthesisFailed) {
180:       result.failure = EvidenceSpeedFailure::kStopSynthesisFailed;
181:       return result;
182:     } else if (candidate_stop.failure == StopFailureReason::kInsufficientSupport) {
183:       candidate_speed = std::nextafter(candidate_speed, 0.0);
184:       if (!std::isfinite(candidate_speed) || candidate_speed <= 0.0) {
185:         result.failure = EvidenceSpeedFailure::kInsufficientSupport;
186:         return result;
187:       }
188:       continue;
189:     } else {
190:       result.failure = stopFailureToSpeedFailure(candidate_stop.failure);
191:       return result;
192:     }
193:   }
194:   result.failure = EvidenceSpeedFailure::kInsufficientSupport;
195:   return result;
196: }
197: 
198: }  // namespace detail
