200: template <typename ShouldAbort>
201: [[nodiscard]] inline EvidenceSpeedLimit evidenceAwareSpeedLimit(
202:     const navigation_math::StatePVAJ& state,
203:     const navigation_planning::DynamicLimits& dynamics,
204:     const std::array<double, 4>& support_m,
205:     const double sample_traj_dt_s,
206:     ShouldAbort&& should_abort) noexcept {
207:   return detail::evidenceAwareSpeedLimitImpl(
208:       state, dynamics, support_m, sample_traj_dt_s,
209:       std::forward<ShouldAbort>(should_abort));
