220: [[nodiscard]] inline EvidenceSpeedLimit evidenceAwareSpeedLimit(
221:     const double configured_speed_mps, const double max_acceleration_mps2,
222:     const double max_jerk_mps3, const std::array<double, 4>& support_m) noexcept {
223:   EvidenceSpeedLimit result;
224:   if (!std::isfinite(configured_speed_mps) || configured_speed_mps <= 0.0 ||
225:       !std::isfinite(max_acceleration_mps2) || max_acceleration_mps2 <= 0.0 ||
226:       !std::isfinite(max_jerk_mps3) || max_jerk_mps3 <= 0.0) {
227:     return result;
228:   }
229:   // This convenience form has no measured boundary state; interpret the
230:   // configured value only as a prospective steady cruise speed.
231:   navigation_math::StatePVAJ state = navigation_math::StatePVAJ::Zero();
232:   navigation_planning::DynamicLimits dynamics;
233:   dynamics.vehicle.maximum_velocity_mps = configured_speed_mps;
234:   dynamics.vehicle.maximum_acceleration_mps2 = max_acceleration_mps2;
235:   dynamics.vehicle.maximum_jerk_mps3 = max_jerk_mps3;
236:   dynamics.intent.requested_cruise_speed_mps = configured_speed_mps;
237:   return evidenceAwareSpeedLimit(state, dynamics, support_m);
238: }
