15: enum class StopFailureReason : std::uint8_t {
16:   kNone,
17:   kInvalidState,
18:   kInvalidDynamics,
19:   kInsufficientSupport,
20:   kOutsideRecoveryEnvelope,
21:   kSynthesisFailed,
22:   kBudgetExhausted,
23: };
24: 
25: struct StopReachability {
26:   bool feasible{false};
27:   double stopping_time_s{0.0};
28:   double stopping_distance_m{0.0};
29:   double estimated_entry_speed_mps{0.0};
30:   double latest_safe_switch_time_s{0.0};
31:   Eigen::Vector3d stop_position{Eigen::Vector3d::Zero()};
32:   StopFailureReason failure{StopFailureReason::kNone};
33: };
34: 
35: // Heuristic full-state seed estimate used only to initialize bounded
36: // polynomial-duration search. It is not a generally conservative bound, stop
37: // certificate, or authorization input.
38: struct StopKinematicEnvelope {
39:   double effective_speed_mps{0.0};
40:   double acceleration_release_s{0.0};
41:   double stopping_time_s{0.0};
42:   double stopping_distance_m{0.0};
43: };
44: 
45: struct BackupBrakingSeed {
46:   double switch_time_s{0.0};
47:   double duration_s{0.0};
48:   navigation_math::Vec3f endpoint{navigation_math::Vec3f::Zero()};
49:   double initial_velocity_mps{std::numeric_limits<double>::infinity()};
50:   double allowed_peak_velocity_mps{std::numeric_limits<double>::infinity()};
51:   double maximum_velocity_mps{std::numeric_limits<double>::infinity()};
52:   double maximum_acceleration_mps2{std::numeric_limits<double>::infinity()};
53:   double maximum_jerk_mps3{std::numeric_limits<double>::infinity()};
54:   double support_bound_m{std::numeric_limits<double>::infinity()};
55:   StopFailureReason failure{StopFailureReason::kNone};
56:   bool initial_overspeed{false};
57:   bool terminal_altitude_preserved{false};
58:   bool feasible{false};
59: };
