61: inline double jerkLimitedStopTime(double speed_mps, double max_acc_mps2,
62:                                   double max_jerk_mps3) {
63:   if (!std::isfinite(speed_mps) || !std::isfinite(max_acc_mps2) ||
64:       !std::isfinite(max_jerk_mps3) || speed_mps < 0.0 ||
65:       max_acc_mps2 <= 0.0 || max_jerk_mps3 <= 0.0) {
66:     return std::numeric_limits<double>::infinity();
67:   }
68:   const double velocity_at_full_accel =
69:       max_acc_mps2 * max_acc_mps2 / max_jerk_mps3;
70:   if (speed_mps <= velocity_at_full_accel) {
71:     return 2.0 * std::sqrt(speed_mps / max_jerk_mps3);
72:   }
73:   return speed_mps / max_acc_mps2 + max_acc_mps2 / max_jerk_mps3;
74: }
75: 
76: inline double jerkLimitedStopDistance(double speed_mps, double max_acc_mps2,
77:                                       double max_jerk_mps3) {
78:   const double stop_time_s =
79:       jerkLimitedStopTime(speed_mps, max_acc_mps2, max_jerk_mps3);
80:   return std::isfinite(stop_time_s)
81:              ? 0.5 * speed_mps * stop_time_s
82:              : std::numeric_limits<double>::infinity();
83: }
84: 
85: inline StopKinematicEnvelope stopKinematicEnvelope(
86:     const navigation_math::StatePVAJ& state, double max_acc_mps2,
87:     double max_jerk_mps3) noexcept {
88:   StopKinematicEnvelope result;
89:   if (!state.allFinite() || !std::isfinite(max_acc_mps2) ||
90:       max_acc_mps2 <= 0.0 || !std::isfinite(max_jerk_mps3) ||
91:       max_jerk_mps3 <= 0.0) {
92:     result.stopping_time_s = std::numeric_limits<double>::infinity();
93:     result.stopping_distance_m = std::numeric_limits<double>::infinity();
94:     return result;
95:   }
96:   const Eigen::Vector3d velocity = state.col(1);
97:   const double speed_mps = velocity.norm();
98:   Eigen::Vector3d direction = Eigen::Vector3d::Zero();
99:   if (speed_mps > 1.0e-9) direction = velocity / speed_mps;
100:   const double longitudinal_acceleration =
101:       std::max(0.0, state.col(2).dot(direction));
102:   const double acceleration_norm = state.col(2).norm();
103:   result.acceleration_release_s = acceleration_norm / max_jerk_mps3;
104:   result.effective_speed_mps = speed_mps +
105:       0.5 * acceleration_norm * result.acceleration_release_s +
106:       0.5 * longitudinal_acceleration * result.acceleration_release_s;
107:   result.stopping_time_s = result.acceleration_release_s +
108:       jerkLimitedStopTime(result.effective_speed_mps, max_acc_mps2,
109:                           max_jerk_mps3);
110:   result.stopping_distance_m =
111:       speed_mps * result.acceleration_release_s +
112:       jerkLimitedStopDistance(result.effective_speed_mps, max_acc_mps2,
113:                               max_jerk_mps3);
114:   return result;
115: }
