117: inline bool refinementDurationRespectsCertifiedFloor(
118:     double candidate_duration_s, double certified_duration_s,
119:     double tolerance_s = 1.0e-9) {
120:   return std::isfinite(candidate_duration_s) &&
121:       std::isfinite(certified_duration_s) &&
122:       std::isfinite(tolerance_s) && certified_duration_s > 0.0 &&
123:       tolerance_s >= 0.0 &&
124:       candidate_duration_s + tolerance_s >= certified_duration_s;
125: }
126: 
127: inline geometry_utils::Piece minimumSnapStopPiece(
128:     const navigation_math::StatePVAJ &initial_state, double duration_s) {
129:   Eigen::Matrix<double, 3, 8> coefficients;
130:   coefficients.setZero();
131:   const auto position = initial_state.col(0);
132:   const auto velocity = initial_state.col(1);
133:   const auto acceleration = initial_state.col(2);
134:   const auto jerk = initial_state.col(3);
135:   const double t2 = duration_s * duration_s;
136:   const double t3 = t2 * duration_s;
137:   const double t4 = t3 * duration_s;
138:   const double t5 = t4 * duration_s;
139: 
140:   // Piece stores descending powers [t^7 ... t 1]. These coefficients are the
141:   // free-end-position minimum-snap polynomial with terminal V/A/J equal zero.
142:   coefficients.col(0).setZero();
143:   coefficients.col(1) =
144:       (-t2 * jerk / 12.0 - duration_s * acceleration / 2.0 - velocity) / t5;
145:   coefficients.col(2) =
146:       (3.0 * t2 * jerk + 16.0 * duration_s * acceleration + 30.0 * velocity) /
147:       (10.0 * t4);
148:   coefficients.col(3) =
149:       (-3.0 * t2 * jerk - 12.0 * duration_s * acceleration - 20.0 * velocity) /
150:       (8.0 * t3);
151:   coefficients.col(4) = jerk / 6.0;
152:   coefficients.col(5) = acceleration / 2.0;
153:   coefficients.col(6) = velocity;
154:   coefficients.col(7) = position;
155:   return geometry_utils::Piece(duration_s, coefficients);
156: }
157: 
158: inline bool isSteadyCruisePVAJ(
159:     const navigation_math::StatePVAJ& state) noexcept {
160:   return state.allFinite() && state.col(2).isZero(0.0) &&
161:       state.col(3).isZero(0.0);
162: }
163: 
164: // Exact minimum duration for the existing minimum-snap stop polynomial when
165: // its prospective entry state has a=j=0. Its continuous extrema are
166: // v_peak=v, a_peak=15v/(8T), and j_peak=10v/(sqrt(3)T^2). This is not an
167: // S-curve optimum and must not be used for a measured non-zero-PVAJ state.
168: inline double minimumSnapSteadyCruiseDuration(
169:     const double speed_mps, const double maximum_acceleration_mps2,
170:     const double maximum_jerk_mps3,
171:     const double sample_traj_dt_s) noexcept {
172:   if (!std::isfinite(speed_mps) || speed_mps < 0.0 ||
173:       !std::isfinite(maximum_acceleration_mps2) ||
174:       maximum_acceleration_mps2 <= 0.0 ||
175:       !std::isfinite(maximum_jerk_mps3) || maximum_jerk_mps3 <= 0.0 ||
176:       !std::isfinite(sample_traj_dt_s) || sample_traj_dt_s <= 0.0) {
177:     return std::numeric_limits<double>::infinity();
178:   }
179:   const long double speed = static_cast<long double>(speed_mps);
180:   const long double acceleration =
181:       static_cast<long double>(maximum_acceleration_mps2);
182:   const long double jerk = static_cast<long double>(maximum_jerk_mps3);
183:   const long double floor = 4.0L * static_cast<long double>(sample_traj_dt_s);
184:   const long double acceleration_duration = 15.0L * speed / (8.0L * acceleration);
185:   const long double jerk_duration = std::sqrt(
186:       10.0L * speed / (std::sqrt(3.0L) * jerk));
187:   const long double duration = std::max(
188:       {floor, acceleration_duration, jerk_duration});
189:   const double result = static_cast<double>(duration);
190:   return std::isfinite(result) && result > 0.0
191:       ? result : std::numeric_limits<double>::infinity();
192: }
193: 
194: inline geometry_utils::Piece minimumSnapStopPieceWithTerminalAltitude(
195:     const navigation_math::StatePVAJ &initial_state, double duration_s,
196:     double terminal_altitude_m) {
197:   const auto free_end_piece = minimumSnapStopPiece(initial_state, duration_s);
198:   if (!std::isfinite(duration_s) || duration_s <= 0.0 ||
199:       !std::isfinite(terminal_altitude_m) || !initial_state.allFinite()) {
200:     return free_end_piece;
201:   }
202: 
203:   const double free_end_altitude_m = free_end_piece.getPos(duration_s).z();
204:   const double altitude_delta_m = terminal_altitude_m - free_end_altitude_m;
205:   const double t2 = duration_s * duration_s;
206:   const double t4 = t2 * t2;
207:   const double t5 = t4 * duration_s;
208:   const double t6 = t5 * duration_s;
209:   const double t7 = t6 * duration_s;
210:   if (!std::isfinite(altitude_delta_m) || !std::isfinite(t4) ||
211:       !std::isfinite(t5) || !std::isfinite(t6) || !std::isfinite(t7) ||
212:       t4 <= 0.0 || t5 <= 0.0 || t6 <= 0.0 || t7 <= 0.0) {
213:     return free_end_piece;
214:   }
215: 
216:   // Add a C^3 smoothstep to the free-end minimum-snap polynomial. The
217:   // smoothstep and its first three derivatives vanish at both endpoints, so
218:   // the measured PVAJ handover and terminal V/A/J=0 remain exact while only
219:   // the terminal altitude is changed. Piece stores descending powers
220:   // [t^7 ... t 1].
221:   auto coefficients = free_end_piece.getCoeffMat();
222:   coefficients(2, 0) += -20.0 * altitude_delta_m / t7;
223:   coefficients(2, 1) += 70.0 * altitude_delta_m / t6;
224:   coefficients(2, 2) += -84.0 * altitude_delta_m / t5;
225:   coefficients(2, 3) += 35.0 * altitude_delta_m / t4;
226:   return geometry_utils::Piece(duration_s, coefficients);
227: }
228: 
229: inline Eigen::Matrix<double, 3, 8> minimumSnapStopBezierControlPoints(
230:     const geometry_utils::Piece &piece) {
231:   const double duration_s = piece.getDuration();
232:   const auto &coefficients = piece.getCoeffMat();
233:   Eigen::Matrix<double, 3, 8> power;
234:   double duration_power = 1.0;
235:   for (int degree = 0; degree <= 7; ++degree) {
236:     power.col(degree) = coefficients.col(7 - degree) * duration_power;
237:     duration_power *= duration_s;
238:   }
239:   constexpr int binomial[8][8] = {
240:       {1, 0, 0, 0, 0, 0, 0, 0},
241:       {1, 1, 0, 0, 0, 0, 0, 0},
242:       {1, 2, 1, 0, 0, 0, 0, 0},
243:       {1, 3, 3, 1, 0, 0, 0, 0},
244:       {1, 4, 6, 4, 1, 0, 0, 0},
245:       {1, 5, 10, 10, 5, 1, 0, 0},
246:       {1, 6, 15, 20, 15, 6, 1, 0},
247:       {1, 7, 21, 35, 35, 21, 7, 1},
248:   };
249:   Eigen::Matrix<double, 3, 8> control_points;
250:   control_points.setZero();
251:   for (int i = 0; i <= 7; ++i) {
252:     for (int k = 0; k <= i; ++k) {
253:       control_points.col(i) += power.col(k) *
254:           static_cast<double>(binomial[i][k]) /
255:           static_cast<double>(binomial[7][k]);
256:     }
257:   }
258:   return control_points;
259: }
260: 
261: inline Eigen::Matrix<double, 3, 8> minimumSnapStopBezierControlPoints(
262:     const navigation_math::StatePVAJ &initial_state, double duration_s) {
263:   return minimumSnapStopBezierControlPoints(
264:       minimumSnapStopPiece(initial_state, duration_s));
265: }
266: 
267: inline double minimumSnapStopSupportBound(
268:     const geometry_utils::Piece& piece,
269:     const Eigen::Vector3d& origin) noexcept {
270:   if (!origin.allFinite() || !std::isfinite(piece.getDuration()) ||
271:       piece.getDuration() <= 0.0 || !piece.getCoeffMat().allFinite()) {
272:     return std::numeric_limits<double>::infinity();
273:   }
274:   const auto control_points = minimumSnapStopBezierControlPoints(piece);
275:   double bound_m = 0.0;
276:   for (Eigen::Index index = 0; index < control_points.cols(); ++index) {
277:     const double control_bound_m =
278:         (control_points.col(index) - origin).norm();
279:     if (!std::isfinite(control_bound_m)) {
280:       return std::numeric_limits<double>::infinity();
281:     }
282:     bound_m = std::max(bound_m, control_bound_m);
283:   }
284:   return bound_m;
285: }
286: 
287: inline double unavoidablePeakSpeedLowerBound(
288:     const navigation_math::StatePVAJ& state,
289:     const double max_jerk_mps3) noexcept {
290:   if (!state.allFinite() || !std::isfinite(max_jerk_mps3) ||
291:       max_jerk_mps3 <= 0.0) {
292:     return std::numeric_limits<double>::infinity();
293:   }
294:   const Eigen::Vector3d velocity = state.col(1);
295:   const double speed_mps = velocity.norm();
296:   if (speed_mps <= 1.0e-9) return speed_mps;
297:   const double longitudinal_acceleration =
298:       std::max(0.0, state.col(2).dot(velocity / speed_mps));
299:   return speed_mps + longitudinal_acceleration * longitudinal_acceleration /
300:       (2.0 * max_jerk_mps3);
301: }
