303: template <typename ShouldAbort>
304: inline BackupBrakingSeed makeBackupBrakingSeedWithAbort(
305:     double switch_time_s, const navigation_math::StatePVAJ &switch_state,
306:     double max_velocity_mps, double max_acc_mps2, double max_jerk_mps3,
307:     double sample_traj_dt_s, double feasibility_margin,
308:     ShouldAbort&& should_abort) {
309:   BackupBrakingSeed result;
310:   result.switch_time_s = switch_time_s;
311:   if (!switch_state.allFinite()) {
312:     result.failure = StopFailureReason::kInvalidState;
313:     return result;
314:   }
315:   if (!std::isfinite(switch_time_s) ||
316:       !std::isfinite(max_velocity_mps) || max_velocity_mps <= 0.0 ||
317:       !std::isfinite(max_acc_mps2) || max_acc_mps2 <= 0.0 ||
318:       !std::isfinite(max_jerk_mps3) || max_jerk_mps3 <= 0.0 ||
319:       !std::isfinite(sample_traj_dt_s) || sample_traj_dt_s <= 0.0 ||
320:       !std::isfinite(feasibility_margin) || feasibility_margin < 0.0) {
321:     result.failure = StopFailureReason::kInvalidDynamics;
322:     return result;
323:   }
324: 
325:   const double speed_mps = switch_state.col(1).norm();
326:   result.initial_velocity_mps = speed_mps;
327:   result.initial_overspeed = speed_mps > max_velocity_mps;
328:   // An observed overspeed cannot be removed instantaneously. Certify that the
329:   // braking polynomial never accelerates beyond the physically unavoidable
330:   // initial speed while retaining the normal mission cap for nominal states.
331:   result.allowed_peak_velocity_mps = std::max(speed_mps, max_velocity_mps);
332:   const double gate = 1.0 + feasibility_margin;
333:   if (!navigation_planning::withinNumericalDynamicLimit(
334:           switch_state.col(2).norm(), gate * max_acc_mps2) ||
335:       !navigation_planning::withinNumericalDynamicLimit(
336:           switch_state.col(3).norm(), gate * max_jerk_mps3) ||
337:       !navigation_planning::withinNumericalDynamicLimit(
338:           unavoidablePeakSpeedLowerBound(switch_state, max_jerk_mps3),
339:           gate * result.allowed_peak_velocity_mps)) {
340:     result.failure = StopFailureReason::kOutsideRecoveryEnvelope;
341:     return result;
342:   }
343:   const auto aborted = [&]() noexcept {
344:     try {
345:       return static_cast<bool>(should_abort());
346:     } catch (...) {
347:       return true;
348:     }
349:   };
350:   const bool steady_cruise = isSteadyCruisePVAJ(switch_state);
351:   double duration_s = 0.0;
352:   int maximum_attempts = 24;
353:   if (steady_cruise) {
354:     duration_s = minimumSnapSteadyCruiseDuration(
355:         speed_mps, max_acc_mps2, max_jerk_mps3, sample_traj_dt_s);
356:     maximum_attempts = 1;
357:   } else {
358:     // Keep the old full-state estimate only as a search seed. Non-zero
359:     // measured acceleration/jerk still use bounded polynomial synthesis.
360:     const auto envelope = stopKinematicEnvelope(
361:         switch_state, max_acc_mps2, max_jerk_mps3);
362:     duration_s = std::max(4.0 * sample_traj_dt_s,
363:                           0.575 * envelope.stopping_time_s);
364:   }
365:   if (!std::isfinite(duration_s) || duration_s <= 0.0) {
366:     result.failure = StopFailureReason::kSynthesisFailed;
367:     return result;
368:   }
369: 
370:   // One uninterruptible unit is construction plus the polynomial extrema and
371:   // Bezier-hull support evaluations for one duration. Abort is observed on
372:   // both sides of that unit; this is not a WCET claim or root-solve preemption.
373:   for (int attempt = 0; attempt < maximum_attempts; ++attempt) {
374:     if (aborted()) {
375:       result.failure = StopFailureReason::kBudgetExhausted;
376:       return result;
377:     }
378:     try {
379:       const auto piece = minimumSnapStopPiece(switch_state, duration_s);
380:       result.duration_s = duration_s;
381:       result.endpoint = piece.getPos(duration_s);
382:       result.maximum_velocity_mps = piece.getMaxVelRate();
383:       result.maximum_acceleration_mps2 = piece.getMaxAccRate();
384:       result.maximum_jerk_mps3 = piece.getMaxJerRate();
385:       const bool finite_extrema = result.endpoint.allFinite() &&
386:           std::isfinite(result.maximum_velocity_mps) &&
387:           std::isfinite(result.maximum_acceleration_mps2) &&
388:           std::isfinite(result.maximum_jerk_mps3);
389:       const bool dynamic_limits_valid = finite_extrema &&
390:           navigation_planning::withinNumericalDynamicLimit(
391:               result.maximum_velocity_mps, gate * result.allowed_peak_velocity_mps) &&
392:           navigation_planning::withinNumericalDynamicLimit(
393:               result.maximum_acceleration_mps2, gate * max_acc_mps2) &&
394:           navigation_planning::withinNumericalDynamicLimit(
395:               result.maximum_jerk_mps3, gate * max_jerk_mps3);
396:       if (dynamic_limits_valid) {
397:         result.support_bound_m = minimumSnapStopSupportBound(
398:             piece, switch_state.col(0));
399:         result.feasible = std::isfinite(result.support_bound_m);
400:       }
401:       if (aborted()) {
402:         result.feasible = false;
403:         result.failure = StopFailureReason::kBudgetExhausted;
404:         return result;
405:       }
406:       if (result.feasible) {
407:         result.failure = StopFailureReason::kNone;
408:         return result;
409:       }
410:       if (steady_cruise) {
411:         result.failure = StopFailureReason::kSynthesisFailed;
412:         return result;
413:       }
414:     } catch (...) {
415:       result.feasible = false;
416:       result.failure = aborted() ? StopFailureReason::kBudgetExhausted
417:                                  : StopFailureReason::kSynthesisFailed;
418:       return result;
419:     }
420:     duration_s *= 1.15;
421:     if (!std::isfinite(duration_s) || duration_s <= 0.0) {
422:       result.failure = StopFailureReason::kSynthesisFailed;
423:       return result;
424:     }
425:   }
426:   result.failure = StopFailureReason::kSynthesisFailed;
427:   return result;
428: }
429: 
430: inline BackupBrakingSeed makeBackupBrakingSeed(
431:     double switch_time_s, const navigation_math::StatePVAJ& switch_state,
432:     double max_velocity_mps, double max_acc_mps2, double max_jerk_mps3,
433:     double sample_traj_dt_s, double feasibility_margin) {
434:   return makeBackupBrakingSeedWithAbort(
435:       switch_time_s, switch_state, max_velocity_mps, max_acc_mps2,
436:       max_jerk_mps3, sample_traj_dt_s, feasibility_margin,
437:       [] { return false; });
438: }
