68: void Planner::setPlannerStage(const int stage) noexcept {
69:     if (!isPlannerTimelineStage(stage)) {
70:         solve_stage_.store(stage);
71:         return;
72:     }
73:     const auto now_steady_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
74:         std::chrono::steady_clock::now().time_since_epoch()).count();
75:     std::lock_guard<std::mutex> guard(planner_timeline_mutex_);
76:     const int previous_stage = solve_stage_.load();
77:     if (previous_stage != stage) {
78:         if (isPlannerTimelineStage(previous_stage)) {
79:             auto& previous = planner_timeline_.stages[static_cast<std::size_t>(previous_stage)];
80:             if (previous.observed && previous.end_steady_ns == 0) {
81:                 previous.end_steady_ns = now_steady_ns;
82:                 previous.remaining_hard_budget_us = remainingPlannerBudgetUs(now_steady_ns);
83:                 previous.result_code = latestReplanReturnCode();
84:             }
85:         }
86:         auto& current = planner_timeline_.stages[static_cast<std::size_t>(stage)];
87:         current.observed = true;
88:         current.begin_steady_ns = now_steady_ns;
89:         current.end_steady_ns = 0;
90:         current.remaining_hard_budget_us = -1;
91:         current.result_code = 0;
92:     }
93:     solve_stage_.store(stage);
94: }
