96: void Planner::finishPlannerTimeline(const int result_code) noexcept {
97:     const auto now_steady_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
98:         std::chrono::steady_clock::now().time_since_epoch()).count();
99:     std::lock_guard<std::mutex> guard(planner_timeline_mutex_);
100:     const int current_stage = solve_stage_.load();
101:     if (isPlannerTimelineStage(current_stage)) {
102:         auto& current = planner_timeline_.stages[static_cast<std::size_t>(current_stage)];
103:         if (current.observed && current.end_steady_ns == 0) {
104:             current.end_steady_ns = now_steady_ns;
105:             current.remaining_hard_budget_us = remainingPlannerBudgetUs(now_steady_ns);
106:             current.result_code = result_code;
