114: AbsoluteDeadline Planner::solveDeadlineForCurrentRequest() const {
115:     if (request_deadline_ns_ > 0) {
116:         const auto now_steady = std::chrono::steady_clock::now();
117:         const auto deadline = std::chrono::steady_clock::time_point(
118:             std::chrono::nanoseconds(request_deadline_ns_));
119:         const double remaining = std::max(
120:             0.0, std::chrono::duration<double>(deadline - now_steady).count());
121:         return AbsoluteDeadline(
122:             planner_context_->getSimTime() + remaining, request_deadline_ns_);
123:     }
124:     return AbsoluteDeadline(planner_context_->getSimTime(), cfg_.solve_deadline_s);
125: }
