129: template <typename Callback>
130: class ScopeExit final {
131:  public:
132:   explicit ScopeExit(Callback callback) : callback_(std::move(callback)) {}
133:   ScopeExit(const ScopeExit&) = delete;
134:   ScopeExit& operator=(const ScopeExit&) = delete;
135:   ~ScopeExit() noexcept {
136:     try {
137:       callback_();
138:     } catch (...) {
139:       // Cleanup is best-effort during exception unwinding. The planner's
140:       // request-local body witness must never escape into a later request,
141:       // while an error from the clear path must not replace the original one.
142:     }
143:   }
144: 
145:  private:
146:   Callback callback_;
147: };
