175:         const navigation_world_model::CurrentBodySupportPtr& body_support = {}) {
176:     if (guide.size() < 2U) return 0.0;
177:     double support_m = 0.0;
178:     bool body_prefix_active = body_support &&
179:         body_support->matchesWorldSnapshot(
180:             world.identity(), body_support->source_stamp_ns) &&
181:         body_support->contains(
182:             guide.front().cast<double>(), world.identity(),
183:             body_support->source_stamp_ns);
184:     for (std::size_t index = 1; index < guide.size(); ++index) {
185:         const Eigen::Vector3d begin = guide[index - 1U].cast<double>();
186:         const Eigen::Vector3d end = guide[index].cast<double>();
187:         const double segment_m = (end - begin).norm();
188:         if (!std::isfinite(segment_m) || segment_m <= 1.0e-9) {
189:             break;
190:         }
191:         if (body_prefix_active && body_support) {
192:             if (!world.isSegmentTraversableWithCurrentBodySupport(
193:                     begin, end, navigation_world_model::GridLayer::kInflated,
194:                     navigation_world_model::UnknownPolicy::kRequireKnownFree,
195:                     body_support)) {
196:                 break;
197:             }
198:             const double body_prefix_fraction =
199:                 body_support->contiguousBodyPrefixFraction(begin, end);
200:             if (!std::isfinite(body_prefix_fraction)) break;
201:             if (body_prefix_fraction >= 1.0 - 1.0e-9) continue;
202: 
203:             const Eigen::Vector3d body_exit = begin +
204:                 body_prefix_fraction * (end - begin);
205:             if (!world.isSegmentTraversable(
206:                     body_exit, end, navigation_world_model::GridLayer::kInflated,
207:                     navigation_world_model::UnknownPolicy::kRequireKnownFree)) {
208:                 break;
209:             }
210:             support_m += (end - body_exit).norm();
211:             body_prefix_active = false;
212:             continue;
213:         }
214:         if (!world.isSegmentTraversable(
215:                 begin, end, navigation_world_model::GridLayer::kInflated,
216:                 navigation_world_model::UnknownPolicy::kRequireKnownFree)) {
217:             break;
218:         }
219:         support_m += segment_m;
220:     }
221:     return support_m;
