2846: void NavigationModeExecutor::onVehicleStatus(
2847:     const px4_msgs::msg::VehicleStatus::UniquePtr& message) {
2848:   if (!message) return;
2849:   px4_hold_confirmed_ =
2850:       message->nav_state == px4_msgs::msg::VehicleStatus::NAVIGATION_STATE_AUTO_LOITER;
2851:   if (px4_hold_confirmed_) {
2852:     hold_handover_pending_ = false;
2853:     hold_handover_in_flight_ = false;
2854:   }
2855: }
