2857: void NavigationModeExecutor::checkHoldHandover() {
2858:   const auto now_steady_ns = navigation_common::steadyClockNowNanoseconds();
2859:   if (hold_handover_pending_ && !px4_hold_confirmed_) {
2860:     if (!hold_handover_in_flight_ && now_steady_ns >= hold_handover_next_retry_steady_ns_) {
2861:       schedulePx4Hold(hold_handover_complete_navigation_failure_);
2862:     }
2863:   }
2864: }
