2866: void NavigationModeExecutor::onActivate() {
2867:   px4_hold_confirmed_ = false;
2868:   hold_handover_pending_ = false;
2869:   hold_handover_in_flight_ = false;
2870:   hold_handover_complete_navigation_failure_ = false;
2871:   hold_handover_attempts_ = 0U;
2872:   hold_handover_next_retry_steady_ns_ = 0;
2873:   RCLCPP_INFO(node_.get_logger(), "Avoidance Mission executor activated");
2874:   scheduleMode(ownedMode().id(), [this](px4_ros2::Result result) {
2875:     onOwnedModeCompleted(result);
2876:   });
2877: }
2878: 
2879: void NavigationModeExecutor::onOwnedModeCompleted(px4_ros2::Result result) {
2880:   if (result == px4_ros2::Result::Deactivated) {
2881:     RCLCPP_DEBUG(node_.get_logger(), "Owned navigation mode was deactivated by mode handover");
2882:     return;
2883:   }
2884:   if (result != px4_ros2::Result::Success) {
2885:     RCLCPP_ERROR(node_.get_logger(), "Avoidance Mission completed with result=%s; handing over to PX4 Hold",
2886:                  px4_ros2::resultToString(result));
2887:     schedulePx4Hold(false);
2888:     return;
2889:   }
2890:   RCLCPP_INFO(node_.get_logger(), "Avoidance Mission completed; handing over to PX4 Hold");
2891:   schedulePx4Hold(false);
2892: }
2893: 
2894: void NavigationModeExecutor::schedulePx4Hold(bool complete_navigation_failure) {
2895:   hold_handover_pending_ = true;
2896:   hold_handover_complete_navigation_failure_ =
2897:       hold_handover_complete_navigation_failure_ || complete_navigation_failure;
2898:   if (px4_hold_confirmed_ || hold_handover_in_flight_) return;
2899:   hold_handover_in_flight_ = true;
2900:   ++hold_handover_attempts_;
2901:   scheduleMode(px4_ros2::ModeBase::kModeIDLoiter,
2902:                [this](px4_ros2::Result hold_result) {
2903:     onPx4HoldHandoverCompleted(hold_result, hold_handover_complete_navigation_failure_);
2904:   });
2905: }
2906: 
2907: void NavigationModeExecutor::onPx4HoldHandoverCompleted(
2908:     px4_ros2::Result result, bool complete_navigation_failure) {
2909:   if (result == px4_ros2::Result::Success || result == px4_ros2::Result::Deactivated) {
2910:     hold_handover_in_flight_ = false;
2911:     hold_handover_pending_ = false;
2912:     RCLCPP_INFO(node_.get_logger(), "PX4 Hold handover completed with result=%s",
2913:                 px4_ros2::resultToString(result));
2914:     return;
2915:   }
2916: 
2917:   hold_handover_in_flight_ = false;
2918:   hold_handover_pending_ = true;
2919:   hold_handover_complete_navigation_failure_ =
2920:       hold_handover_complete_navigation_failure_ || complete_navigation_failure;
2921:   constexpr std::int64_t kHoldRetryPeriodNs = 250'000'000LL;
2922:   hold_handover_next_retry_steady_ns_ =
2923:       navigation_common::steadyClockNowNanoseconds() + kHoldRetryPeriodNs;
2924:   RCLCPP_ERROR_THROTTLE(
2925:       node_.get_logger(), *node_.get_clock(), 5000,
2926:       "PX4 Hold handover attempt=%u failed with result=%s; keeping the explicit "
2927:       "stationary safety stream and retrying until AUTO_LOITER is confirmed",
2928:       hold_handover_attempts_, px4_ros2::resultToString(result));
2929: }
2930: 
2931: void NavigationModeExecutor::onDeactivate(DeactivateReason reason) {
2932:   px4_hold_confirmed_ = false;
2933:   hold_handover_pending_ = false;
2934:   hold_handover_in_flight_ = false;
2935:   hold_handover_complete_navigation_failure_ = false;
2936:   hold_handover_attempts_ = 0U;
2937:   hold_handover_next_retry_steady_ns_ = 0;
2938:   RCLCPP_INFO(node_.get_logger(), "Avoidance Mission executor deactivated (%s)",
2939:               reason == DeactivateReason::FailsafeActivated ? "failsafe" : "mode_exit");
2940: }

